/* CHI participant menu — content.
   Stages, the 67 tiles, the icon set, agency names, CHI contacts, route wording.
   This is the file a coordinator edits. No logic, no secrets. */

const STAGES = [
  {n:1, key:'home', t:'I am still in my country', z:'My country',   d:'I have not flown to the United States yet.', c:'Visa, flights, dates, housing, my documents'},
  {n:2, key:'arr',  t:'I just arrived',            z:'Just arrived', d:'I landed in the last two weeks.',            c:'First day, SEVIS, Social Security, housing'},
  {n:3, key:'work', t:'I am working',              z:'Working',      d:'Questions about my job, my hours and my pay.', c:'Hours, pay, my manager, changing jobs'},
  {n:4, key:'life', t:'Living in the USA',         z:'Living here',  d:'Everything that is not about my job.',        c:'Health, safety, documents, travel, housing'},
  {n:5, key:'end',  t:'My program is ending',      z:'Ending',       d:'I am close to my end date or already home.', c:'Going home, final pay, taxes, next year'}
];

const T = [
{s:'home', q:'When is the next online orientation', sub:'Sessions, attendance, the certificate', g:'Before you book anything', ic:'webinar', r:'Answer', k:'orientation session webinar zoom next when schedule missed attendance certificate mandatory link slides recording gba absent marked',
 you:'You start on <b>{dsStartF}</b>. Try to join a session before then. Cannot join? Tell your CHI team before the session, not after.',
 lead:'There is always another session. The dates come to your email and your WhatsApp group.',
 body:['Missing one is not a problem. The same topics come round again. Join the next one.','Join with your Student ID in your Zoom name. Write it like this: Andrei Ionescu 52341. Without the number, nobody can match you to your record. You are marked absent even though you were there.','Fill in the attendance form during the session. Do not wait until the end.','The form closes when the session closes. Fill it in later and it says the session has ended. It does not count. This is the number one reason people are marked absent when they sat there the whole time.','Were you there, but the record says you were not? Tell your CHI team two things. The date. And the exact name you used in Zoom. This gets fixed.','Cannot join live, because of exams or the time difference? Tell your CHI team before the session. Not after.'],
 need:['The date of the session','The name you used in Zoom','Your Student ID'],
 act:{label:'I was marked absent but I was there', kind:'team'},
 w:{trigger:'Tile opened, or the action tapped', fires:'Nothing automatic', captures:'Session date, Zoom display name used, SID', notify:'Coordinator, batched not immediate', log:'Orientation Log corrected against the SID', status:'build', note:'This is the biggest single thing in the orientation data and it is not a programme question at all. 134 of 771 questions asked in the sessions, 17 percent, are about the attendance link failing, being marked absent after attending, or whether there is another session. Two of those three are a form problem rather than a participant problem: the Tally window closes at the end of the session and the Zoom display name has to carry the SID for matching to work. Fixing the form removes most of this tile. Until then the tile at least stops the question arriving as a WhatsApp message during the session itself.'}},
{s:'home', q:'My visa appointment', sub:'Visa, embassy, DS-160', r:'Answer', mo:['embassy_status','Embassy Status Update Request, or Embassy Denial if the visa is refused. Greeting resolves to the agency POC from the lookup table.'], g:'Before you book anything', ic:'passport', k:'visa embassy consulate ds160 interview appointment',
 you:'You are coming through <b>{agencyName}</b> in <b>{country}</b>. They book your appointment, not CHI.',
 lead:'Your agency at home books your embassy appointment. CHI does not book it.',
 body:['CHI does two things. CHI gives you your DS-2019 form. CHI pays your SEVIS fee.','Your agency does the rest. The DS-160 form. The appointment date. The interview itself.','So ask your agency, not CHI.','Is your appointment after your start date? Tell your agency now. CHI can write a letter to move your dates. But your agency has to ask for it.'],
 need:['Your DS-2019, the paper one','Your SEVIS fee receipt','Your job offer'],
 act:{label:'Message my agency', kind:'agency'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'live', note:'Highest volume question in the whole inbox at 622 replies. Pure answer, no CHI action, no form. Build this one first.'}},
{s:'home', q:'Where is my DS-2019', sub:'Waiting for my DS form', g:'Before you book anything', ic:'docn', r:'Agency', k:'ds2019 ds-2019 ds form coming waiting arrive sent tracking not received where is my form document sponsor letter sponser job offer difference',
 you:'You are coming through <b>{agencyName}</b> in <b>{country}</b>. They are the ones who put the DS-2019 in your hands. When it arrives the dates on it should read <b>{dsStartF}</b> to <b>{dsEndF}</b>.',
 lead:'CHI issues it and sends it to your agency. Your agency gets it to you, so ask them for the tracking.',
 body:['You cannot book your embassy appointment without it. If your interview is close and the form has not arrived, tell your agency today.','The day it arrives, check three things before anything else: your name spelled exactly as it is in your passport, your date of birth, and the start and end dates.','If any of those are wrong, say so before your embassy appointment. A correction after the visa is issued is much harder and much slower.','Photograph it the day you get it and keep the photo somewhere you can find it. A replacement costs 75 dollars and takes time.','Bring the paper form to your interview. A photo is not accepted at the embassy.','The DS-2019 is not the same as your job offer, and it is not the same as the sponsor letter. The DS-2019 is the government form with your programme dates. The job offer is from your employer. The sponsor letter is the one that says CHI sponsors you, and it is the one the Social Security office asks for. All three come from different places and you will need all three.'],
 need:['Your agency contact','Your embassy appointment date, if you have one'],
 act:{label:'Message my agency', kind:'agency'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'live', note:'Routes to the agency named from Agency Office Code, which is why the tile can say who to chase instead of saying your agency. The three checks matter more than the chasing: a name or date error caught before the embassy appointment costs nothing, and the same error caught after the visa is issued becomes a correction letter and a delayed arrival.'}},
{s:'home', q:'I need to change my start date', sub:'Delays, exams, moving my dates', g:'Before you book anything', ic:'calswap', r:'Agency', k:'dates change start date end date university exams classes term semester study go home early late master degree graduation school starts delay delayed late visa embassy correction letter push back postpone',
 you:'Your programme runs <b>{dsStartF}</b> to <b>{dsEndF}</b>, and <b>{employer}</b> built their season around the first of those.',
 lead:'Tell your agency the moment you know. Your employer has to agree before any date moves, and they need warning.',
 body:['The two reasons dates move are a delay and your university. A delay is your embassy appointment, your visa or your DS-2019 arriving late. Your university is exams finishing after your start date, or term beginning before your end date.','If your exams end after your start date, tell your agency now, not in May. A few days late can sometimes be arranged with the employer. A few weeks cannot.','If your classes start before your end date, say so now. It is much easier to shorten a programme before it is issued than after you have arrived.','If you are a postgraduate with no fixed autumn classes, or it is your final year, you still need proof you are enrolled. Bring it.','If something is delaying you, your embassy appointment, your visa, your DS-2019 or an exam that moved, tell your agency the moment you know. Do not wait to see whether it resolves itself.','A few days late can usually be arranged with the employer. A few weeks often cannot, and the placement can go to somebody else.','CHI can issue a correction letter to move your dates, but only after your employer agrees, and it is far simpler before your DS-2019 has been used at the embassy.','If your dates changed after your visa was issued, your DS-2019 and your correction letter will not match. That is normal. Carry both, and never travel with only one of them.','CHI does not have your academic calendar. Only you and your agency do, which is why this conversation starts with them.'],
 need:['Your term start date','Your exam dates','Written proof you are still enrolled'],
 act:{label:'Message my agency', kind:'agency'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'live', note:'Merged from two tiles because the orientation questions show it is one problem. Across 899 orientation questions, university term dates come up repeatedly and always as a dates question: exams after the start date, classes before the end date, no autumn classes for postgraduates. Routes to the agency named from Agency Office Code. CHI has been asked to confirm return dates it cannot know, which is why this tile never offers an answer.'}},
{s:'home', q:'Can CHI check my housing is not a scam', sub:'Before I pay anyone anything', g:'Before you book anything', ic:'shieldalert', r:'Team', hz:1, k:'scam fraud fake housing check verify landlord deposit facebook money transfer before i pay lease listing safe legit',
 you:'You are placed with <b>{employer}</b> in <b>{location}</b>. If housing is not provided there, send CHI anything you find before you pay a cent.',
 lead:'Yes, and send it before you pay anything. After the money is gone CHI cannot get it back.',
 body:['Send your CHI team the listing, the address, the landlord full name and their phone number. That takes a day to check and it is free.','These are the signs. They want the whole deposit by bank transfer, gift card or crypto before you have seen anything. The price is far below everything else in the same town. They will not do a video call. They say they are abroad and cannot show you the place. They push you to decide today.','Never send money to someone you have only met in a Facebook group or a WhatsApp chat without CHI looking at it first. That is where almost all of these start.','Ask for the lease in writing before you pay. A real landlord will give you an address, a full name, a phone number and a lease. If you cannot get all four, you have your answer.','If you have already sent money and it has gone wrong, tell your CHI team anyway. It may be too late for the money, but not for your housing.'],
 need:['The listing or the advert','The address','The landlord full name and phone number','What they are asking you to pay, and how'],
 act:{label:'Ask CHI to check this housing', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing automatic', captures:'Listing, address, landlord name and number, amount and payment method requested', notify:'Coordinator, marked time sensitive because money is usually about to move', log:'Case row, category Housing. Address flagged if it matches an earlier report', status:'build', note:'Only bites for participants whose employer does not provide housing, which is a minority but the one with real money at risk. Worth logging the addresses: a scam listing gets sent to a whole cohort, so the second report at the same address should be instant rather than another day of checking.'}},
{s:'home', q:'How early can I arrive', sub:'Arriving before my start date', g:'Before you book anything', ic:'shieldplane', r:'Answer', k:'early arrive how many days before start date insurance uninsured supplement land arrive early extra cover',
 you:'Your programme starts <b>{dsStartF}</b>. You can land any time from <b>{earlyOk}</b>. That is free. Land before that day and you pay for extra insurance.',
 lead:'Seven days before your start date is free. Earlier than that, you pay for extra insurance.',
 body:['Your insurance starts on the start date printed on your DS-2019. Not on the day you land.','Every day you are in the USA before that date, you have no medical insurance at all.','Do you want to come more than seven days early? Tell your CHI team the exact date before you buy your ticket. The extra insurance costs money, and someone has to set it up for you.','Do not come early and stay quiet. One visit to a clinic in a week with no insurance costs more than your insurance for the whole programme.','Your employer may not be ready for you either. Housing usually opens a few days before your start date. Not weeks before.'],
 clock:{l:'Before you book', t:'Tell your CHI team your landing date before you buy the ticket, not after.'},
 need:['The day you plan to land','The start date on your DS-2019'],
 act:{label:'Tell my CHI team my landing date', kind:'form'},
 w:{trigger:'Arrival Date minus DS Start is 8 days or more', fires:'Early arrival insurance notice with the cost, to the participant and their agency', captures:'Landing date, uninsured days, supplement owed', notify:'Coordinator', log:'Msg_Early_Arrival_Insurance stamped on the roster row', status:'build', note:'The seven day line is the whole answer and the tile now says it as a date rather than a rule, so nobody has to count. 14 participants landed 8 to 21 days early this season, roughly 1450 dollars of exposure, and the roster column for this trigger already exists while the trigger itself does not.'}},
{s:'home', q:'Where do I enter my visa results', sub:'After the embassy, approved or refused', g:'Before you fly', ic:'visastamp', r:'File', k:'visa result approved refused denied embassy interview enter report portal administrative processing passport back stamp',
 you:'Your programme starts <b>{dsStartF}</b>. Nothing after this point can be arranged until your visa result is recorded.',
 lead:'In your CHI portal, the same day you leave the embassy. Approved or refused, both have to be entered.',
 body:['Enter it the day you know. Your arrival information, your housing confirmation and your group cannot be finalised while your visa result is blank.','If you were approved, enter the date and add a photo of the visa page once your passport comes back. Check three things on it: your name, your date of birth, and whether the Entries field says M or S.','If you were refused, enter that too. Nobody is in trouble for a refusal. CHI needs to know at once so your agency can advise you and so your placement can be handled properly.','If you were told administrative processing, enter that. It is not a refusal, but it has its own timeline and everything after it has to be planned around it.','Do not book a flight until the visa is physically in your passport. An approval at the window is not the same as a visa in your hand.'],
 need:['Your interview date','The result','A photo of the visa page, once you have your passport back'],
 act:{label:'Enter my visa result', kind:'form'},
 w:{trigger:'Form submitted. Chased at DS Start minus 30 if still blank', fires:'Approved: arrival information unlocked. Refused: Embassy Denial to the agency contact. Administrative processing: Embassy Status Update', captures:'Interview date, result, visa page image, Entries M or S', notify:'Coordinator. Agency contact on a refusal', log:'Date Visa Received, Date Visa Denied and Visa Approved written to the roster', status:'build', note:'The roster already has all three columns and nothing feeds them. CHI Advisor already has Embassy Denial and Embassy Status Update written, so the sends exist and only the capture is missing. Catching Entries S here rather than in July is the other reason for the tile: a single entry visa changes every travel answer for the whole programme.'}},
{s:'home', q:'Where do I enter my flight details', sub:'Flights, airport, landing date', r:'File', g:'Before you fly', ic:'plane', k:'flight ticket airport arrival landing itinerary plane',
 you:'We have you landing on <b>{arrivalF}</b>, and your programme starts <b>{dsStartF}</b>. If your flight has changed, send the new details.',
 lead:'Send your flight details as soon as you book, even if the date might change.',
 body:['Your CHI team needs your landing date to check two things: that your insurance is running when you land, and that your housing address is in SEVIS before you arrive.','If your plans change later, send the new details. It is never a problem to update.'],
 need:['Airline and flight number','Landing airport and landing date','Your first US address if you already have it'],
 sample:{title:'Email you can send your employer', lines:[
   'Subject: My arrival details, {name}',
   '',
   'Dear [manager name],',
   '',
   'My name is {name} and I am joining you at {employer} in {location} as a {job}.',
   '',
   'My programme starts on {dsStartF}. Here are my arrival details:',
   '',
   'Landing airport: [airport]',
   'Landing date: [date]',
   'Landing time: [time]',
   'Airline and flight number: [flight]',
   '',
   'Please can you confirm where I should go on my first day, what time to be there, and who to ask for.',
   '',
   'Thank you, and I am looking forward to the season.',
   '',
   '{name}',
   'CHI Student ID: {sid}']},
 act:{label:'Send my flight details', kind:'form'},
 w:{trigger:'Form submitted', fires:'Flight Information template to the participant', captures:'Flight number, landing date, arrival airport, first address', notify:'Log row only', log:'Arrival Date, Arrival Airport, Arrival Airline and Arrival Flight Number written to Staging Participants', status:'build', note:'No flight form exists yet. Roster already has Arrival Date, Arrival Airport, Arrival Airline and Arrival Flight Number columns waiting to be fed.'}},
{s:'home', q:'Where do I verify my housing', sub:'Where I will live, and getting it verified', hz:1, g:'Before you fly', ic:'housekey', r:'File', k:'housing house live where stay accommodation room apartment before arrive rent cost landlord verify verified address sevis link form',
 you:'You are placed with <b>{employer}</b> in <b>{location}</b>, starting <b>{dsStartF}</b>. Your address has to reach CHI before you fly.',
 lead:'Whoever arranges your housing, CHI has to verify the address before you land.',
 body:['Read the housing section of your job offer first. It says whether housing is provided, what it costs each week, and whether that cost comes out of your pay.','If your offer says you find your own, start now. Your CHI team can send you the housing list for your area, but they cannot rent a room for you.','Either way, send the address through the link below as soon as you have it. Include the apartment or room number. A missing unit number is the single most common reason verification fails.','WHY THIS IS REQUIRED: CHI is required to enter your US housing address into SEVIS, the US government tracking system for J-1 students, before you arrive. If your housing is not in SEVIS when you land, you can be denied entry at the airport. This is not optional. Please complete the form as soon as you can.','If the address changes before you fly, send the new one. There is no penalty for updating it.'],
 need:['Your full US address including the apartment or room number','The name and phone number of your landlord or housing provider','What the housing costs each week','The date you move in'],
 act:{label:'Get my housing verified', kind:'form'},
 w:{trigger:'Form submitted. Chased at DS Start minus 21 and minus 10 if nothing has been received', fires:'Verification confirmation to the participant once the address passes', captures:'Full address with unit number, provider name and phone, weekly cost, move in date', notify:'Coordinator if it arrives under 10 days before landing, or not at all', log:'Housing Approved Address and Housing Status written to the roster', status:'build', note:'No form exists for this yet and it is the one pre-arrival tile with a hard consequence: no address in SEVIS means a participant can be turned away at the border. The required wording is Jenn own and must go out unchanged. The chase matters more than the form: the failure mode is not a wrong address, it is no address at all, and nothing currently watches for silence.'}},
{s:'home', q:'What airport should I fly into', sub:'Choosing the airport and getting out of it', g:'Before you fly', ic:'depart', r:'Answer', k:'airport fly into best nearest which airport transport shuttle pickup taxi bus train from the airport late night transfer connection two flights',
 you:'You are going to <b>{location}</b>. Before you book, ask your CHI team which airport other people at <b>{employer}</b> use.',
 lead:'Fly to the airport named on your job offer. Is no airport named? Ask before you book.',
 body:['The closest airport is not always the right one. And the cheapest flight is often not the cheapest trip.','A cheap flight to a big airport four hours away costs more, once you pay to get from there to your housing.','Before you book, work out how you will get from the airport to your housing. Most employers do not pick you up. Your job offer says so if yours does.','Are you landing in the evening? Check the last bus or train first. In small towns there is often nothing at night. A taxi can cost more than your flight did.','Keep money for this trip. It can be a hundred dollars or more. That money comes out of what you brought for your first two weeks.','Do you have two flights? Only put the flight that lands in the USA into your portal.','Landing late at night with no way to get there? Tell your CHI team before you book. Not after.'],
 need:['Your job offer','The address of your housing','Your airport and your landing time'],
 act:{label:'Ask my CHI team about my area', kind:'team'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Asked in the orientations about Fairbanks, Estes Park and other remote placements, where the honest answer is that there may be no transport after the evening at all. The right airport per host area is a short list CHI could write once and reuse every season, shown from Location Name.'}},
{s:'home', q:'When should I contact my employer', sub:'Reaching them before I fly', g:'Before you fly', ic:'envelope', r:'Team', k:'contact employer reach out email phone number job description no response reply before arrival week before manager',
 you:'Your employer is <b>{employer}</b> in <b>{location}</b>. You are going as a <b>{job}</b>, starting <b>{dsStartF}</b>.',
 lead:'Email them about a week before you fly, using the contact on your job offer.',
 body:['If your job offer only has an email address, use the email. Most seasonal employers do not answer a phone before the season opens.','Tell them your name, your Student ID, your job title and your landing date, and ask three things: where to go on your first day, what time to be there, and who to ask for.','Expect it to be slow. A week with no reply before the season starts is normal. Two weeks is not.','If there is no contact on your job offer at all, or nobody has answered after two weeks, tell your CHI team and they will chase it for you.','Silence usually means they are not open yet. It does not usually mean something is wrong.'],
 need:['Your job offer','The date you emailed them','Any reply you did get'],
 act:{label:'Nobody has replied, tell my CHI team', kind:'team'},
 w:{trigger:'Form submitted, only when they escalate', fires:'Nothing automatic', captures:'Date emailed, contact used, whether any reply came', notify:'Coordinator', log:'Case row, category Communication, only if escalated', status:'build', note:'Straight from the orientation questions: no phone number on the job description, no reply after nine days, and job offers that say contact your employer a week before arrival while giving a contact that does not answer. The tile mostly exists to set the expectation that slow is normal, which stops the message arriving at CHI on day three.'}},
{s:'home', q:'WhatsApp groups for my employer', sub:'The group for my employer', g:'Before you fly', ic:'chatgroup', r:'File', k:'whatsapp group add me chat added join not in the group number sim employer group left group removed',
 you:'You are placed with <b>{employer}</b> in <b>{location}</b>. That is the group you belong in.',
 lead:'Your CHI team adds you to the group for your employer once your placement is confirmed.',
 body:['There is one group for each employer, and sometimes one for each location. It is where arrival information, first day details and anything that affects everybody gets posted.','You are added using the WhatsApp number CHI has for you. If you have changed your number, or you are about to use a new SIM in the United States, send the new number or you will not be added.','You can be added before you fly. If your start date is close and you are still not in a group, ask.','If you left by accident, changed phone, or lost the number, ask to be put back in. Nobody is removed on purpose.','Anything about you personally, your pay, your housing, your documents, goes to your CHI team directly. Do not post it in the group.'],
 need:['The number you actually use for WhatsApp, with the country code','Your employer name'],
 act:{label:'Add me to the group', kind:'form'},
 w:{trigger:'Form submitted', fires:'Confirmation once added', captures:'WhatsApp number with country code, employer', notify:'Coordinator, to add them', log:'WhatsApp column updated on the roster', status:'build', note:'Adding is manual, so the value here is the number, not the request. The roster WhatsApp column is what every group invite and every direct message runs off, and it goes stale the moment someone buys a US SIM. This tile and the US phone number tile in the arrival board write to the same column, which is deliberate: one before they fly, one after they land.'}},
{s:'home', q:'Where is my job description or offer', sub:'Job offer and job description', g:'Before you fly', ic:'formsign', r:'Answer', k:'job offer description contract where find portal download signed saved copy lost access pay rate housing hours position',
 you:'CHI has you as a <b>{job}</b> at <b>{employer}</b> in <b>{location}</b>, starting <b>{dsStartF}</b>. Open your offer. Does it say those same four things? If not, tell your CHI team today.',
 lead:'It is in your CHI portal, under your profile. It stays there after you sign it.',
 body:['Your job offer and your job description are the same paper. It names your employer, your town, your job, your pay, your hours, and whether housing is included.','Did you sign it and not save a copy? It is still in the portal. Signing does not delete it.','Download it today and keep it on your phone. Do not leave it only in the portal.','You will check things against this paper all season. Your pay rate on your pay stub, which is the paper that comes with your wages here. What you were told about housing. Who to contact before you arrive.','Print two copies. One for your embassy interview. One for your first day at work.','Is the job you are doing different from this paper? Then this paper is your proof. That is why you want it before you need it.'],
 need:['Your CHI portal login'],
 act:{label:'Ask my CHI team for my job offer', kind:'team'},
 w:{trigger:'Tile opened, or the action tapped', fires:'Nothing automatic. A person sends it if the portal copy is missing', captures:'Nothing', notify:'Coordinator only when they ask for it', log:'Page view only', status:'live', note:'The most referenced document in the whole menu. Twelve other tiles tell a participant to check something against their job offer, so a tile that says where it is has more leverage than its own question volume suggests. The personal line is doing real work here: it prints the four fields from the roster and asks the participant to compare them with the paper, which is the cheapest possible check on a placement record being wrong.'}},
{s:'home', q:'What documents do I need', sub:'The six papers to carry', g:'Before you fly', ic:'docstack', r:'Answer', k:'documents papers passport ds2019 visa job offer sponsor letter enrolment student proof insurance card i94 carry hand luggage what do i need bring',
 you:'You fly to <b>{location}</b> and start on <b>{dsStartF}</b>. Every item on this list goes in your hand luggage. None of them go in a checked bag.',
 lead:'Six documents. Keep all six in your hand luggage. Put none of them in a bag you check in.',
 body:['One. Your passport, with the J-1 visa inside it.','Two. Your DS-2019. The paper one. A photo on your phone is not accepted at the embassy or at the border.','Three. Your job offer, printed.','Four. Your sponsor letter. This is the letter that says CHI is your sponsor. It is not your job offer. It is not your DS-2019. It is a third, separate paper. The Social Security office asks for it by name.','Five. Proof that you are still a student. In English, if your university can do that.','Six. Your insurance card. Download it from your CHI portal and print it before you fly.','Now take a photo of all six. Email the photos to yourself. If a bag goes missing, those photos are what get you through the next two days.','At the border you will be asked for two things. Your passport and your DS-2019. Hold those two. Do not put them in the bag above your seat.','On your first day at work you will be asked for three things. Your passport, your DS-2019, and your printed I-94. The I-94 is your US entry record. You print it after you land, not before.','Do not laminate anything. Do not fold your DS-2019.'],
 need:['Passport with the visa','DS-2019, the paper one','Job offer','Sponsor letter','Proof you are a student','Insurance card'],
 act:{label:'Send me the document checklist', kind:'template'},
 w:{trigger:'Tile opened, and on a send at DS Start minus 14', fires:'Document checklist', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'build', note:'Split out from what should I bring because the two lists behave differently: forget a jumper and you buy one, forget the DS-2019 and you do not board. The sponsor letter is on here deliberately even though nothing at the airport asks for it, because it is the item people leave at home and then need at the Social Security office ten days later. No template written yet.'}},
{s:'home', q:'Where can I find my sponsor letter', sub:'The letter that says CHI sponsors you', g:'Before you fly', ic:'letter', r:'Answer', k:'sponsor letter sponser visa sponsor where find get portal social security office not the job offer difference',
 you:'Your sponsor letter shows your name, your Student ID <b>{sid}</b>, and your dates <b>{dsStartF}</b> to <b>{dsEndF}</b>. Check those three before you fly.',
 lead:'It is in your CHI portal, with your other documents. Not there? Ask your CHI team and they will send it.',
 body:['It is a letter on CHI paper that says CHI is your sponsor. It has your name, your Student ID and your programme dates on it.','It is not your job offer. It is not your DS-2019. Those three are different papers, from three different places.','Many people bring two of the three. They find out at the Social Security office that they needed all three.','The Social Security office asks for this letter by name. Some banks ask for it too.','Print it before you fly. Do not plan to download it on your phone while you stand in a queue.','Check that your name on it is spelled the same as your passport. Wrong spelling is easy to fix now. It is hard to fix at the counter.'],
 need:['Your CHI portal login'],
 act:{label:'Ask my CHI team for my sponsor letter', kind:'team'},
 w:{trigger:'Tile opened, or the action tapped', fires:'Nothing automatic. The letter is sent by a person if the portal copy is missing', captures:'Nothing', notify:'Coordinator only when they ask for it', log:'Send logged against SID', status:'build', note:'Asked five separate times in the orientation Q and A, always as some version of what is the sponsor letter and how is it different from the job offer. Two things to confirm before this goes live: whether the letter actually sits in the participant portal alongside the DS-2019 copy and the proof of address, and whether it can be generated on demand. If it is not in the portal, this becomes a File tile with a request form rather than an Answer tile.'}},
{s:'home', q:'What should I bring', sub:'Documents, clothes, money, medicine', g:'Before you fly', ic:'suitcase', r:'Answer', k:'bring pack packing documents clothes weather cold hot medicine prescription vaccine vaccination supplements food money cash phone unlock sim carry on suitcase',
 you:'You are going to <b>{location}</b> and you start on <b>{dsStartF}</b>. Before you pack, look up the real temperature there for those months. It will not be what you expect.',
 lead:'Money, medicine, and clothes for the real weather. Documents are a separate tile.',
 body:['Documents have their own list. Open the documents tile above and check it before you close your bag.','Bring money for two to three weeks. Your first paycheck does not come in your first week. You will need rent, food and travel before it arrives.','Bring the medicine you take every day. Keep it in the box it came in. Bring the prescription, or a letter from your doctor.','Bring enough medicine for the whole programme. Getting a foreign prescription filled here is slow and costs a lot.','Do you carry needles or insulin? Keep the doctor letter with them.','Do not bring medicine that belongs to someone else. Do not bring anything you cannot show a prescription for. Vitamins are fine in either bag.','Look up the real temperature where you are going, for the months you will be there. It will not be what you expect.','Air conditioning indoors here is very cold. Beach towns are hot and wet. Northern states can still be cold in June. Bring one warm layer.','Unlock your phone before you leave home. A phone locked to your home network will not take a US SIM card. This is the number one reason people arrive and nobody can reach them.','Bring shoes you can stand in for eight hours. You will be on your feet more than you think.'],
 need:['Money for two to three weeks','Your medicine, plus the prescription or a doctor letter','A phone that is unlocked','Shoes you can stand in all day'],
 act:{label:'Read this and go back', kind:'answer'},
 w:{trigger:'Tile opened, and on a send at DS Start minus 14', fires:'Nothing on view', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'This was a thin tile until the orientation questions were read. What they actually ask about is clothes for the weather where they are going, whether they can bring their own medicine, vaccines and supplements, and whether their phone will work. The climate line personalises off Location Name, which is the only part that varies. Worth firing as a send two weeks before departure rather than waiting to be asked.'}},
{s:'home', q:'Can I get a second job before I arrive', sub:'Arranging one from home', g:'The job and the money', ic:'twobags', r:'Answer', k:'second job before i arrive get find arrange mandatory need required extra work another job apply now form when from home',
 you:'Your main job is <b>{job}</b> at <b>{employer}</b>. That is the one your programme is built on.',
 lead:'No. You cannot set one up before you land. And you do not have to have one at all.',
 body:['Your first job comes first, always. A second job has to fit around that schedule.','Do not say yes to a second job before you land. You will not know your main hours until you start. And they change every week.','Do not fill in the second job form now. Fill it in when you have a real offer in front of you.','CHI must approve any second employer before your first shift there. Working somewhere CHI has not approved puts your visa at risk.','Most people who want a second job find one after a few weeks. By then they know their main hours and they know their area.','So the answer for now is: wait. There is nothing you need to do today.'],
 need:[],
 act:{label:'Read this and go back', kind:'answer'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Second job was 5 percent of all orientation questions, asked before arrival, and almost every one of them was is it mandatory, where do I find one, or should I fill the form now. All three have the same short answer, which is why this is an Answer tile here and a File tile in the working board.'}},
{s:'home', q:'Can I start my Social Security', sub:'Applying before I arrive', g:'The job and the money', ic:'card', r:'Answer', k:'social security ssn apply before arrive now online start application sponsor letter visa appointment book',
 you:'You arrive for a programme starting <b>{dsStartF}</b>. You will be able to apply about ten days after you land, not before.',
 lead:'No. You have to be in the United States first. Here is the order it goes in.',
 body:['One. You land.','Two. You send CHI your US address.','Three. CHI checks you in on the government system. This is called validating your SEVIS record.','Four. Now you can apply. This is usually about ten days after you land.','You cannot skip a step. If you apply before step three, you are refused and you start again. Applying early costs you time. It does not save you time.','What you can do today is know what you will need. Your passport. Your DS-2019. Your printed I-94, which you get after you land. And your sponsor letter.','The sponsor letter is the letter that says CHI is your sponsor. It is not your job offer and it is not your DS-2019. The Social Security office asks for it by name. No sponsor letter? Ask your CHI team now.','You can start work before your card arrives. Tell your employer you have applied. Show them the receipt.'],
 need:['Passport','DS-2019','Your sponsor letter'],
 act:{label:'Send me the Social Security steps', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'SSN next steps template', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'fix', note:'Social Security was 8 percent of orientation questions and most of them were asked before arrival: can I apply now, can I apply without the visa, where is the sponsor letter. The answer is no and here is the order, which is cheap to give early and expensive to give late. Same template gap as the arrival tile: no SSN template has been written yet.'}},
{s:'arr', q:'Where do I go on my first day', sub:'First day, reporting, who to ask for', r:'Answer', mo:['intervention','Intervention Required, only when nobody at the employer is expecting them.'], ic:'doorin', k:'first day arrive report where go employer start manager check in',
 you:'Go to <b>{employer}</b> in <b>{location}</b>. Your job title is <b>{job}</b>. The address and the manager to ask for are on your job offer.',
 lead:'Go to the address on your job offer. Ask for the manager named on it.',
 body:['Is nobody expecting you? Do not leave the building. Stay there and call the number on your job offer.','Nobody answers that number either? Message your CHI team right away. Tell them the address you are standing at.','Do not go home and wait. Someone can help you while you are still there.'],
 need:['Your job offer','The phone number of your employer'],
 act:{label:'I am there and nobody is expecting me', kind:'team'},
 w:{trigger:'Tile opened, or escalation tapped', fires:'Nothing automatic on view', captures:'Location and employer if escalated', notify:'Coordinator, marked urgent, on escalation only', log:'Case row opened only if escalated', status:'live'}},
{s:'arr', q:'My housing when I land', sub:'Is it what I was promised, is it safe', r:'File', mo:['intervention','Intervention Required with the photos attached.'], hz:1, ic:'housecrack', k:'housing house bad dirty unsafe unlivable mold broken no bed promised different arrive land first',
 you:'Your placement is <b>{employer}</b> in <b>{location}</b>.',
 lead:'Take dated photos before you move anything, then file this. Photos are what let your CHI team act.',
 body:['Describe what is wrong in plain words: no bed, no hot water, no lock on the door, more people than beds, pests.','Your CHI team contacts the housing provider and the employer. This is not something to argue with a landlord alone.','If you feel unsafe right now, do not file a form. Use the message button at the bottom of this page.'],
 need:['Photos with the date visible','The address','How many people are in the unit','What you were told before you arrived'],
 act:{label:'File a housing report', kind:'form'},
 w:{trigger:'Form submitted', fires:'Acknowledgment to participant, no promise of outcome', captures:'Photos, address, occupancy, what was promised', notify:'Coordinator immediately, employer contact drafted', log:'Case row, category Housing', status:'live', note:'Housing Safety and Welfare Check form is already live. Point the tile at it rather than writing a new one.'}},
{s:'arr', q:'How do I get my I-94', sub:'I-94, entry record', r:'Answer', ic:'printer', k:'i94 i-94 entry record arrival departure cbp',
 you:'Use your name exactly as it appears in your passport, and your landing date of <b>{arrivalF}</b>.',
 lead:'Your I-94 is your US entry record. It is free. You print it yourself from a government website.',
 body:['Search the internet for I-94 CBP. Open the official site. Choose Get Most Recent I-94.','Type your name exactly as it is printed in your passport.','Does it say no record found? Try your first name and family name the other way round.','Still nothing? Look at your passport number again. A zero can look like the letter O, and a one can look like the letter I.','Print it. You need it for your Social Security application. Your employer will ask for it too.'],
 need:['Your passport number','Your date of birth','Your name exactly as in your passport'],
 act:{label:'Send me the I-94 instructions', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Get I-94 template', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'live', note:'Template exists and is complete.'}},
{s:'arr', q:'How do I validate my SEVIS record', sub:'SEVIS validation, address in SEVIS', r:'Answer', mo:['sevis','The MO team completes the SEVIS entry. Field staff enters it in the portal first, then the SEVIS template tells MO to complete it.'], ic:'pincheck', k:'sevis validate validation activate address registration',
 you:'This has to be done by <b>{sevisBy}</b>. That is 30 days after your start date of <b>{dsStartF}</b>.',
 lead:'Send your US address to CHI after your first night in it. This one has a legal deadline.',
 body:['The government needs to know where you live. CHI does this for you, but CHI needs your real address first.','Until this is done, two things are true. You are not officially in status. And you cannot apply for a Social Security Number.','Send the full address. Street, number, and your apartment or room number.','The missing room number is the number one reason this fails. If you live in room 4B, write 4B.'],
 clock:{l:'This has a legal clock', t:'Your record must be validated within 30 days of your program start date.'},
 need:['Your full street address','Your apartment, room or unit number','City, state and ZIP code'],
 act:{label:'Send my address for SEVIS', kind:'form'},
 w:{trigger:'Form submitted', fires:'SEVIS validation confirmation once processed', captures:'Full address with unit', notify:'Coordinator daily digest', log:'Sevis Validation Date written to the roster', status:'build', note:'Roster already carries Sevis Validation Date and Sevis Status Description. Nothing currently watches an unvalidated record past day 20.'}},
{s:'arr', q:'How do I apply for my Social Security Number', sub:'SSN, social security card', r:'Answer', ic:'card', k:'ssn social security number card apply receipt appointment office validated sevis',
 you:'Apply by <b>{ssnBy}</b> at the very latest. That is 45 days before your programme ends on <b>{dsEndF}</b>. After that a card cannot reach you in time.',
 lead:'Wait until CHI has checked you in on the government system. That is usually about ten days after you land.',
 body:['That check is called validating your SEVIS record. Apply before it is done and you are refused, and you have to start again.','Apply online first. Then go to the Social Security office in person. Take your passport, your DS-2019 and your printed I-94.','They give you a receipt. Keep it. CHI does not need a copy of it.','Show that receipt to your employer. It proves you have applied. You can work before the card arrives.','The card comes in the post two to five weeks later.','Have four weeks passed with no card? It is not coming on its own. Search this page for card has not come and follow those steps.'],
 clock:{l:'This has a deadline', t:'Apply at least 45 days before your DS-2019 end date, or the card will not arrive in time.'},
 need:['Passport','DS-2019','Printed I-94','Your US address'],
 act:{label:'Read this and go back', kind:'answer'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'The receipt is deliberately not collected. CHI does not chase cards, so a receipt upload would be a form that creates work and answers nothing. The participant keeps it for their employer. Highest message volume item on the arrival board, and the whole of it is the order of the four steps, which is why this is an Answer and not a form.'}},
{s:'arr', q:'How do I fill in my employment paperwork', sub:'I-9, W-4, first day forms', r:'Answer', ic:'formsign', k:'employment paperwork i9 i-9 w4 w-4 forms fill in tax withholding first day hire onboarding',
 you:'<b>{employer}</b> will hand you these forms on your first day.',
 lead:'Your employer gives you forms on your first day. Go slowly. Ask before you guess.',
 body:['Nobody expects you to know these forms. Ask questions. That is normal here.','The I-9 form proves you are allowed to work. Bring your passport, your DS-2019 and your printed I-94. You do not need your Social Security card for it.','The W-4 form is your tax form. This is the one that goes wrong most often.','On the W-4, you are almost certainly what the US calls a nonresident. That means you fill it in differently from an American. Say so, and ask for help with that line.','Get this wrong and the wrong tax comes out of every paycheck, all season.','Do not tick the box that says US citizen or permanent resident. Tick the box that says you are allowed to work.','Do they ask for a Social Security number you do not have yet? Say you have applied. Show them your receipt. You can start work without the number.','Ask for a copy of everything you sign. Keep it. If money goes missing from your pay in week six, these papers are how it gets checked.'],
 need:['Passport','DS-2019','Printed I-94','Your SSN receipt, if you have it'],
 act:{label:'Send me the paperwork guide', kind:'template'},
 w:{trigger:'Tile opened or action tapped, and on placement', fires:'Employment Paperwork Guide template', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'live', note:'Template already exists. The W-4 nonresident point is what prevents the FICA problem three tiles later, so the two should reference each other.'}},
{s:'arr', q:'How do I get a US phone number', sub:'SIM card, prepaid, keeping WhatsApp', r:'Answer', ic:'phone', k:'phone number sim card prepaid mobile cell service plan contract whatsapp esim',
 you:'Once you have a number, send it to your CHI team. Right now the only way we can reach you is your email, <b>{emailMask}</b>.',
 lead:'Buy a prepaid SIM card. You do not need a Social Security number for it.',
 body:['Prepaid means you pay first, then use it. No contract. No credit check.','You can buy one on your first day, at a phone shop or a large supermarket. Take your passport.','Do not sign a monthly contract in your first weeks. Contracts need a Social Security number and a credit history you do not have yet. They also last longer than your programme.','Your phone must be unlocked. A phone locked to your home network will not take a US SIM card. Unlock it before you leave home.','The same day you get your new number, send it to two places. Your employer. And your CHI team.','That number is how anyone reaches you in an emergency. Do not leave it until next week.','Keep your home number on WhatsApp if you can. Then your family still reaches you on the same account.'],
 need:['Your passport','A phone that is unlocked'],
 act:{label:'Send my CHI team my US number', kind:'form'},
 w:{trigger:'Form submitted', fires:'Confirmation to the participant', captures:'New US number', notify:'Nobody', log:'WhatsApp column updated on the roster', status:'build', note:'Small tile, real payoff. Participants change numbers and the roster keeps the old one, which is how people become unreachable and end up as an Unresponsive Participant email.'}},
{s:'arr', q:'How do I open a US bank account', sub:'Bank account, direct deposit', r:'Answer', ic:'bank', k:'bank account open money debit card direct deposit branch savings checking cash',
 you:'Take an employer letter from <b>{employer}</b> with you.',
 lead:'Take your passport, your DS-2019 and your US address. You do not need your Social Security card first.',
 body:['Take a letter from your employer too. Some branches want proof that you are working.','Ask your employer which bank other participants use. Then getting paid straight into your account is much faster to set up.','Ask for an account with no monthly fee. Some accounts take a few dollars every month, quietly, forever.','Never give your bank card or your login to anyone. Not a roommate. Not a landlord. Not a manager.','Did the branch say no? That happens. Try a different branch, or a different bank. It is not about you.'],
 need:['Passport','DS-2019','Your US address','A letter from your employer'],
 act:{label:'Ask my CHI team which bank is nearest', kind:'team'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Which branches open accounts for J-1 participants varies by host city. Content should be written per area and shown from Location Name on the roster.'}},
{s:'arr', q:'How do I get to work', sub:'Transport, bus, bikes, walking', r:'Answer', ic:'bicycle', k:'transport bus bike walk get to work travel commute jitney train',
 you:'You work at <b>{employer}</b> in <b>{location}</b>.',
 lead:'Most participants walk or cycle. Ask your employer what the other people in your housing do.',
 body:['Buy a second hand bike in your first week. It is cheap, and it means you can take a second job later.','Check the time of the last bus before you say yes to a closing shift.','Being stuck at work at midnight with no bus is the transport problem your CHI team hears about most.'],
 need:[],
 act:{label:'Ask my CHI team about my area', kind:'team'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Answer varies by location. Content should be written per host city and shown from Location Name on the roster.'}},
{s:'arr', q:'I need casino fingerprinting', sub:'Fingerprinting, GBA, casino badge', r:'Answer', ic:'finger', k:'casino licence license fingerprint gba badge dge registration',
 you:'You are placed with <b>{employer}</b> in <b>{location}</b>. Is that a casino? Then you cannot start on the floor until your fingerprinting is cleared.',
 lead:'Working in a casino? You cannot start on the floor until your fingerprinting is done and cleared.',
 body:['Your employer books the appointment. Not you, and not CHI.','Take your passport, your DS-2019, and your Social Security receipt if you have one.','There is a fee. Most employers take it out of your first pay.','Ask your manager how much it is before you go, so it is not a surprise on your first paycheck.'],
 need:['Passport','DS-2019','The appointment details from your employer'],
 act:{label:'Send me the fingerprinting guide', kind:'template'},
 w:{trigger:'Placement at a casino employer, or tile opened', fires:'Casino Fingerprinting template', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'fix', note:'Template exists but jumps from Section 2 to Section 4, uses an all caps headline at weight 800 and off brand colours. Fix before wiring the placement trigger.'}},
{s:'arr', q:'I moved to a new address', sub:'Address change, SEVIS update', r:'File', mo:['sevis','Address has to reach SEVIS within ten days, so this goes to MO the same day it is filed.'], hz:1, ic:'housemove', k:'moved address change new place relocate update sevis housing house move out',
 you:'We have you working at <b>{employer}</b> in <b>{location}</b>. Send the new address even if you are still nearby.',
 lead:'Tell CHI within ten days of moving. This is a legal requirement, not a formality.',
 body:['CHI must enter your US address into SEVIS, the US government system that tracks J-1 participants. If your address in SEVIS is wrong, your record can be affected.','Send the full new address including apartment or room number, and the date you moved.'],
 clock:{l:'This has a legal clock', t:'Ten days from the day you move.'},
 need:['Full new address with unit number','The date you moved','Who else is living there, if CHI placed them too'],
 act:{label:'Update my address', kind:'form'},
 w:{trigger:'Form submitted', fires:'Address change confirmation', captures:'New address, move date, roommates', notify:'Coordinator, SEVIS update task', log:'Housing Approved Address updated. Case row if the move is within 10 days of arrival', status:'build', note:'No form exists yet. Use the exact required wording about being denied entry, unchanged.'}},
{s:'work', q:'I am not getting enough hours', sub:'Low hours, slow weeks, 32 hours', r:'Team', mo:['intervention','Intervention Required, but only after three short weeks and only with the stubs attached.'], g:'My hours and my pay', ic:'clock', k:'hours not enough slow week 32 hours short cut shifts schedule empty',
 you:'You are on day <b>{day}</b> of <b>{len}</b> at <b>{employer}</b>. Send every stub you have had since you started.',
 lead:'32 hours is an average across your whole program, not a promise for every week.',
 body:['Slow weeks are normal. Rain closes boardwalk business, the start and end of the season are quiet, and shifts get cut when a manager sends people home early.','Under three short weeks is too early to call it a pattern. Keep every pay stub.','Three weeks or more of short hours is a pattern, and your CHI team will contact your employer. Without your stubs they are guessing when they make that call.'],
 need:['Every pay stub since you started','A photo of the posted schedule','What your manager said when you asked','Whether you missed or called out of any shifts'],
 act:{label:'Send my stubs and schedule', kind:'team'},
 w:{trigger:'Form submitted with at least 3 stubs', fires:'Nothing to the participant automatically', captures:'Stub images, schedule photo, manager response, missed shifts', notify:'Coordinator, subject sortable as Hours, employer, SID', log:'Case row, category Hours. Paycheck Log fed', status:'build', note:'No template written. Paycheck Log sheet exists with zero rows against 42 pay cases: build the feeder before the list.'}},
{s:'work', q:'My pay is wrong', sub:'Wrong hours, wrong rate, deductions', r:'Team', mo:['intervention','Intervention Required once the employer has been contacted and not resolved it.'], g:'My hours and my pay', ic:'billx', k:'pay wrong wage rate deduction short money paid less paycheck incorrect',
 you:'You are a <b>{job}</b> at <b>{employer}</b> in <b>{location}</b>. Check the rate on your stub against the rate on your job offer before you file.',
 lead:'Upload one pay stub. Your CHI team cannot call an employer about pay without seeing the stub.',
 body:['Choose what is wrong: the hours are short, the rate is wrong, the deductions are too high, or you never received it.','Check the rate against your job offer before you file. Many rate questions turn out to be a training rate for the first weeks, which the offer already said.'],
 need:['One pay stub, photo or PDF','Your job offer','What you think is wrong'],
 act:{label:'Upload my pay stub', kind:'team'},
 w:{trigger:'Stub uploaded. The alert does not fire without it', fires:'Nothing to the participant automatically', captures:'Stub, issue type from a short list, employer, agency, DS dates, weeks in program', notify:'Coordinator, subject line Pay, employer, SID, issue', log:'Case row, category Payroll. Paycheck Log fed', status:'build', note:'Upload gate is the point. An email reply can be words; an upload field cannot.'}},
{s:'work', q:'What tax comes out of my pay', sub:'Tax, tips and overages', g:'My hours and my pay', ic:'formpct', r:'Answer', k:'tax taxes deducted automatic paycheck tips overtime overage overages refund return april w2 fica social security medicare exempt',
 you:'You are a <b>{job}</b> at <b>{employer}</b>. You should be able to see everything below on the pay stub in your hand.',
 lead:'Tax comes out of your pay by itself. You do not pay it yourself.',
 body:['Federal tax and state tax are taken out before you are paid. You do nothing. It just happens.','Tips are taxed here. Overtime is taxed too. Cash tips still count as money you earned.','Now the important part. Two taxes should NOT be taken from your pay at all. Social Security tax and Medicare tax. J-1 participants do not pay these.','Look at your pay stub. That is the paper that comes with your wages. Look for these words: FICA, OASDI, SS, Med, or FED MED EE.','Do you see any of them? That is money taken by mistake. You can get it back. Tell your CHI team now, not in three months.','Next April you send a tax form to the US government. You do this from home. You do not need to be in the USA.','Almost everyone pays too much tax on a summer wage. That form is how you get the extra money back.','Before you leave, give your workplace an address that still works in January. That is where they send your W-2, the paper you need for that form.'],
 need:['Your newest pay stub','Your job offer, so you can check your hourly pay'],
 act:{label:'Read this and go back', kind:'answer'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Tax was 3 percent of orientation questions and always the same three: is it automatic, are tips taxed, do I get an overage back. Putting the FICA line here rather than only in the working board is what catches the wrong deduction in week one instead of week six.'}},
{s:'work', q:'There is Social Security or Medicare on my check', sub:'FICA, OASDI, wrongly deducted tax', r:'File', g:'My hours and my pay', ic:'receiptsearch', k:'fica oasdi medicare social security tax deduction withheld exempt refund overage overages 843 8316',
 you:'If this is on your stub at <b>{employer}</b>, it is almost certainly on the stubs of everyone else CHI placed there.',
 lead:'J-1 participants do not pay Social Security or Medicare tax. If it is on your stub, it should not be.',
 body:['On your stub it may be written as FICA, OASDI, SS, Med or FED MED EE. Almost nobody recognises these words, which is why it goes unnoticed for months.','Upload one stub and your CHI team will tell you yes or no within a day.','This is almost never one person. If it is happening to you it is usually happening to everyone from your employer.','Caught now, your employer can simply correct it and pay you back. Left until the tax year closes, it becomes a claim to the IRS on its own forms and a wait of most of a year. Search this page for tax overages for that route.'],
 need:['One pay stub showing the deduction lines'],
 act:{label:'Check my stub', kind:'form'},
 w:{trigger:'Form submitted', fires:'FICA outcome template, yes or no', captures:'Stub, employer', notify:'Coordinator, plus automatic check of every participant at that employer', log:'Case row, category Payroll. Employer flagged', status:'build', note:'One submission must trigger a cohort check at that employer. Ocean Casino ran three people; Hard Rock was a Workday setup problem.'}},
{s:'work', q:'I did not get my paycheck', sub:'Missing check, wrong address', r:'Team', g:'My hours and my pay', ic:'envcash', k:'paycheck not received missing lost mail direct deposit address check',
 lead:'Nine times out of ten the check went to an old address.',
 body:['Tell your employer your current address in writing, and ask whether the check was posted or held at the workplace.','If it was posted more than ten days ago and never arrived, your CHI team will contact payroll.'],
 need:['The address payroll has for you','The pay period that is missing','Whether you are on direct deposit'],
 act:{label:'Message my CHI team', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing automatic', captures:'Address on file, pay period, deposit or check', notify:'Coordinator', log:'Case row, category Payroll', status:'build'}},
{s:'work', q:'My time off was refused', sub:'Days off, holiday, time off request', r:'Answer', g:'My hours and my pay', ic:'calx', k:'time off holiday vacation refused denied days off request leave',
 you:'Only <b>{employer}</b> can approve your time off. CHI cannot.',
 lead:'CHI cannot give you time off. Only your employer can.',
 body:['This is not CHI saying no. CHI has no power over your schedule.','Your employer planned the whole season around the people they hired. Summer is their busiest time.','So time off is hardest to get in exactly the weeks you most want it. That is normal, and it is not personal.','Ask early. Ask in a message, so there is a record.','Best trick: offer to swap the shift with someone. Ask your manager to approve the swap. This works far more often than just asking for the day off.'],
 need:[],
 act:{label:'Read this and go back', kind:'answer'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'live', note:'One line answer. Costs 349 replies a season as a conversation.'}},
{s:'work', q:'I have a problem with my manager', sub:'Manager, supervisor, being shouted at', r:'Team', mo:['intervention','Intervention Required for anything that is not ordinary direct feedback.'], g:'My job and the people I work with', ic:'people', k:'manager supervisor boss problem rude shouting unfair treated favouritism',
 you:'You are working at <b>{employer}</b> in <b>{location}</b>.',
 lead:'Tell your CHI team what happened. A person will read this, not a machine.',
 body:['Managers in the United States give direct feedback and correct mistakes on the spot. That is normal here and it is not personal.','What is not normal is being shouted at, singled out, threatened or treated differently from American staff. Those are the things to report.','Write down the date, what was said and who else was there. Details a week old are much harder to act on.'],
 need:['What happened and when','Who else saw it','Whether it has happened before'],
 act:{label:'Message my CHI team', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing. This tile never auto replies', captures:'Free text, dates, witnesses', notify:'Coordinator immediately', log:'Case row, category Employment', status:'live', note:'Costs 588 replies, the third most expensive topic in the inbox, and no page can settle it. The tile is worth building as intake only.'}},
{s:'work', q:'I have a problem with a coworker', sub:'Someone I work with, not my manager', g:'My job and the people I work with', ic:'talkpair', r:'Answer', k:'coworker colleague workmate teammate problem argument rude lazy not doing their job blaming gossip conflict',
 you:'You are working at <b>{employer}</b> in <b>{location}</b>.',
 lead:'Try to fix it yourself first. Say something within two days, before you get angry.',
 body:['People work differently in different countries. Someone who sounds rude to you may just be direct. Someone who seems slow may have been trained another way.','So not every problem is a problem to report.','When you speak to them, say what happened to you. Do not say what kind of person they are.','Do not say: you never restock anything.','Say: I cannot finish my side when the trays are empty. Can we agree who fills them?','Do it soon. Wait two weeks and the talk goes badly. By then you are angry, and they still do not know anything was wrong.','Is it about shifts, tips or money? Go to your manager instead. Do not talk to the coworker about that.','Do you also live with this person? Use the housing tile instead. Home problems are handled a different way.'],
 need:['What happened, and when','Have you said anything to them yet','Do you live with them too'],
 act:{label:'This did not work, message my CHI team', kind:'team'},
 w:{trigger:'Tile opened. Nothing sends unless they tap through to the team', fires:'Nothing automatic', captures:'Free text if escalated', notify:'Coordinator only on escalation', log:'Case row, category Communication, only if escalated', status:'build', note:'Split out from the manager tile on purpose. Together they were 65 threads and 588 replies, the third most expensive topic in the inbox, but they are two different problems. A manager problem is a power problem and CHI contacts the employer. A coworker problem is usually a peer problem the participant can solve, and the I statements page from the orientation deck is what solves it. Splitting them means the cheap half stops arriving as a case. Threats, unwanted touching, or being singled out for where they are from is neither of these tiles: that is the unsafe tile and it goes straight to a person.'}},
{s:'work', q:'I was sent home from a shift', sub:'Sent home, suspended, told not to come in', r:'Team', g:'My job and the people I work with', ic:'doorout', k:'sent home shift suspended told not to come back stood down',
 you:'Ask <b>{employer}</b> one question in writing: am I on next week schedule.',
 lead:'Being sent home from one shift is not the same as being fired. Do not assume the worst yet.',
 body:['Ask your manager one question in writing: am I on next week schedule.','Send your CHI team the answer. If you are still on the schedule this is a bad shift, not the end of your job.','If you are not on the schedule, say so straight away. There is a ten day clock and it starts on the day the job ends.'],
 need:['What you were told and by whom','Whether you are on the next schedule','The date'],
 act:{label:'Message my CHI team', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing automatic', captures:'What was said, schedule status, date', notify:'Coordinator immediately', log:'Case row, category Employment', status:'build', note:'Frequently mistaken for termination. Separating the two here prevents a 10 Days template firing on someone who still has a job.'}},
{s:'work', q:'I lost my job', sub:'Fired, terminated, let go', r:'Team', mo:['unplacement','Unplacement Notification with the reason, then Mid-Atlantic Offering if a replacement position is found inside the region.'], g:'My job and the people I work with', ic:'bagx', k:'fired terminated lost job let go dismissed sacked no longer employed',
 you:'You are on day <b>{day}</b> of <b>{len}</b>. Your programme ends <b>{dsEndF}</b>, and the ten days start from your last day of work, not from today.',
 lead:'Tell your CHI team today. A clock starts the day the job ends.',
 body:['You have ten days to be placed in a new approved job. That is not ten working days.','Bring what you can: what you were told, the date, and anything in writing. Your CHI team will contact the employer for their side.','Do not start looking for work on your own until you have spoken to your CHI team. An unapproved job makes this worse, not better.'],
 clock:{l:'This has a legal clock', t:'Ten days from the last day of work.'},
 need:['The date the job ended','What you were told and by whom','Anything in writing'],
 act:{label:'Message my CHI team now', kind:'team'},
 w:{trigger:'Form submitted', fires:'10 Days template', captures:'Last day, reason given, documents', notify:'Coordinator and manager immediately', log:'Case row, category Employment, severity High. Termination Tracker fed', status:'fix', note:'10 Days template exists. Termination Tracker sheet has zero rows. Do not fire this template on someone who was only sent home from one shift.'}},
{s:'work', q:'How do I get a second job approved', sub:'Approval, vetting, before my first shift', g:'Adding or changing my job', ic:'twobags', r:'File', k:'second job extra work another job additional employment more hours approved approval vetting authorised authorized side job',
 you:'Your main job is <b>{job}</b> at <b>{employer}</b>. Anything you add has to fit around that schedule, not the other way round.',
 lead:'You can hold a second job, but CHI has to approve the employer before your first shift there.',
 body:['Tell your CHI team before you start, not after. Working somewhere that has not been approved is unauthorised employment, and that puts your visa at risk. If you have already worked a shift there, say so on the form. It is fixable, and hiding it is not.','Send the employer details: the legal business name, the address, the manager name and phone number, your job title, your pay rate and the hours they want from you.','CHI then checks that the employer is a legal placement and carries workers compensation insurance. That check is the part that takes time, so allow about a week and do not agree to a start date until it is done.','You will get an approval to sign. Once that comes back, you can start.','Almost all second jobs are approved. Around one in five participants has one, so this is normal, not a special request.','Once it is approved you have a monthly evaluation for the second job as well as your main one.','Your main job always comes first. If the second job starts taking shifts you owe your main employer, the second one has to go.'],
 need:['Legal business name and address of the new employer','Manager name and phone number','Your job title and pay rate','The hours they want from you','Whether you have already worked a shift there'],
 act:{label:'Send my second job for approval', kind:'form'},
 w:{trigger:'Form submitted', fires:'Second Job template to the participant, plus a vetting request to the new employer for the workers compensation certificate', captures:'Employer legal name, address, manager, rate, hours, start date, already started yes or no', notify:'Coordinator. Urgent flag when already started is yes, because that is unauthorised employment and the clock is already running', log:'Second Job Host Business written to the roster. Case row, category Employment. Monthly evaluation obligation added', status:'live', note:'Costs 599 replies, the second most expensive topic in the whole inbox, and 106 of 494 participants have one. Template exists. Two things to get right. The already started question is the whole point of the tile: people find the job and then tell you, so the form has to catch that rather than assume the right order. And the workers compensation certificate is what stalls every one of these, so the vetting request should go to the employer the moment the form lands, not after a coordinator reads it.'}},
{s:'work', q:'My casino fingerprinting', sub:'Not cleared yet, or needed for a new job', g:'Adding or changing my job', ic:'finger', r:'Answer', k:'casino licence license badge fingerprint gba dge registration not issued waiting second casino job renewal lost badge fee deducted cannot start floor',
 you:'You are a <b>{job}</b> at <b>{employer}</b> in <b>{location}</b>, on day <b>{day}</b> of <b>{len}</b>.',
 lead:'Ask your employer first, not CHI. Your employer is told when it clears, before you are.',
 body:['Your employer books the fingerprinting. Your employer gets the result. So your manager knows before anyone else.','Go and ask your manager where it is. That is the fastest answer you can get.','Are you being kept off the schedule while you wait? That is lost hours and lost money.','Write down every week you were free to work and got no shifts. If this goes past two weeks, send that list to your CHI team.','Do you want a second job at another casino? It needs its own fingerprinting. The one you already have does not move with you.','Did you lose the badge or card your employer gave you? Tell them the same day. Do not wait.','There is a fee. Most employers take it out of your pay. Ask how much, and which week, so it is not a shock.'],
 need:['The date you were fingerprinted','What your manager has told you','The weeks you were free but got no shifts'],
 act:{label:'Send me the fingerprinting guide', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Casino Fingerprinting template', captures:'Nothing', notify:'Coordinator only if lost hours are reported', log:'Send logged against SID', status:'fix', note:'Second copy of the arrival tile, worded for the middle of the programme where the question changes from how do I get it to where is it. CHI and the participants both say fingerprinting, not licence, so the tiles say that too. Same template behind both, and it still jumps from Section 2 to Section 4, uses an all caps headline at weight 800 and off brand colours. The lost hours line is the part that matters: fingerprinting stuck in processing shows up as an hours complaint weeks later and nobody connects the two.'}},
{s:'work', q:'Can I change to a different employer', sub:'Job change, new employer, resign', r:'File', mo:['placement','Placement Update, then SEVIS Date Update if the dates move with the new employer.'], g:'Adding or changing my job', ic:'swap', k:'change job new employer quit resign different job transfer leave',
 you:'You are on day <b>{day}</b> of your programme. You need 30 days served at <b>{employer}</b> before a change is possible.',
 lead:'Do not resign until CHI has the three documents from your new employer in hand.',
 body:['You need 30 days served, your Social Security number already given to your current employer, and your new employer job offer, workers compensation certificate and signed agreement received by CHI.','The workers compensation certificate is the one that holds everything up. Ask for it first.','Resigning before that is approved starts a ten day clock with no job at the end of it.'],
 clock:{l:'This has a clock', t:'If you leave a job with nothing approved, you have ten days to be placed or your program ends.'},
 need:['New job offer','New employer workers compensation certificate','30 days served at your current job','Your notice, not given yet'],
 act:{label:'Start a job change', kind:'form', url:'tally.so/r/aQyZxb'},
 w:{trigger:'Form submitted', fires:'Job Change template with the document checklist', captures:'New employer, offer, workers comp certificate, notice date', notify:'Coordinator. Chase scheduled at 3 and 7 days for missing documents', log:'Job Changes sheet fed. Case row, category Employment', status:'fix', note:'Form live at tally.so/r/aQyZxb. Job Changes sheet has zero rows against 62 job change cases. Template merge field is the square bracket style, matching the script.'}},
{s:'work', q:'Can I make my second job my main job', sub:'Swap primary and secondary', r:'File', mo:['sevis','SEVIS swap only. No vetting, no new placement record, because that employer is already approved.'], g:'Adding or changing my job', ic:'starbag', k:'second job primary main swap switch make primary secondary hours',
 you:'Your current main job is <b>{job}</b> at <b>{employer}</b>. This is a swap, not a new second job.',
 lead:'This is the simplest of the three job changes and the one filed wrong most often.',
 body:['Your second employer is already approved, so there is nothing to vet. No new workers compensation certificate, and no new fingerprinting.','What is needed is notice to your current main employer, written confirmation that the second employer will give you full hours, and the SEVIS swap done by CHI.','Say clearly that this is a swap, not a new second job. Filing it as a second job sends it down the wrong path.'],
 need:['Written confirmation of full hours from the second employer','Your notice date at the current main job'],
 act:{label:'Swap my primary job', kind:'form'},
 w:{trigger:'Form submitted', fires:'Primary swap confirmation', captures:'Second employer, confirmed hours, notice date', notify:'Coordinator, SEVIS swap task', log:'Case row, category Employment', status:'build', note:'No template and no form yet. Aleksandrina Gerasimova SID 60617 in August 2026 had a primary swap processed as a second job. That misfile is why this tile exists separately.'}},
{s:'work', q:'Something else about my job', sub:'Anything not on this board', g:'Anything else', ic:'askbubble', r:'Team', k:'other something else not listed different question anything else help job work',
 you:'You are working as a <b>{job}</b> at <b>{employer}</b> in <b>{location}</b>, on day <b>{day}</b> of <b>{len}</b>.',
 lead:'If your question is about your job and it is not on this board, write it here.',
 body:['Tell your CHI team what is happening in your own words. It does not have to be written well and you do not need to know what to call it.','Say what has already happened, what you have already tried, and what you want to change. Those three things are what let a person actually help rather than write back asking questions.','A person reads this. Nothing automatic is sent.'],
 need:['What is happening','What you have already tried','What you want to happen next'],
 act:{label:'Message my CHI team', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing. This tile never auto replies', captures:'Free text, plus SID, employer, agency, DS dates and day in programme attached automatically', notify:'Coordinator', log:'Case row, category left blank for the coordinator to set', status:'build', note:'The standing rule is fail toward a human, and this is where that happens on the busiest board. It matters that it carries the participant context automatically: in the vacation window, 7 of 43 threads were people who only said hello and never stated their question, and several of those went to another coordinator instead. A free text box with the SID already attached turns that into something answerable on the first reply.'}},
{s:'life', q:'I was in an accident', sub:'Injured at work, car accident, incident', g:'Medical and safety', ic:'warntri', r:'Team', k:'accident injured hurt at work injury workers compensation comp car crash fell burn cut incident report claim',
 you:'You are working at <b>{employer}</b> in <b>{location}</b>. Your insurance runs <b>{dsStartF}</b> to <b>{dsEndF}</b>.',
 lead:'If it is serious, call 911 first. Then tell your manager and your CHI team the same day.',
 body:['If you were hurt at work, say so out loud to your manager on the day it happened, and in writing if you can. An injury reported a week later is much harder for anyone to help with.','An injury at work is covered by your employer workers compensation, not by your travel insurance. Tell the clinic or the hospital that it happened at work, because they bill it differently.','An injury away from work, or a car accident, goes through your insurance instead. Keep every bill and every receipt.','Photograph whatever caused it and write down the names of anyone who saw it happen. Memories and rotas both disappear fast.','Tell your CHI team either way, even if you feel fine afterwards. Some injuries are reported by the employer and CHI has to know before that happens, not after.'],
 need:['What happened, where and on what date','Whether you were working at the time','Who saw it','Any bills or paperwork you already have'],
 act:{label:'Message my CHI team now', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing automatic. Medical Help template only if they also select that they need care', captures:'What happened, date, at work yes or no, witnesses, bills', notify:'Coordinator and manager immediately. Marked time sensitive', log:'Case row, category Wellbeing, Safety Incident. Hospitalised and DoS Notified columns set where they apply', status:'build', note:'Split out from sick or hurt because the money and the paperwork run down two different routes. At work means workers compensation and an employer report. Away from work means the travel insurance. Getting that wrong at the clinic is what produces a bill nobody will pay. There were 16 safety incidents and 24 sick or injured cases this season and no tile separated them.'}},
{s:'life', q:'I am sick or I am hurt', sub:'Doctor, hospital, insurance, Teladoc', r:'Answer', mo:['intervention','Intervention Required only when hospitalised is selected. Everything else stays with the coordinator.'], g:'Medical and safety', ic:'heartpulse', k:'sick hurt ill injured doctor hospital medical insurance teladoc urgent care pain',
 you:'Your insurance runs <b>{dsStartF}</b> to <b>{dsEndF}</b>. Keep every bill inside those dates.',
 lead:'Is this an emergency? Call 911. Is it not an emergency? Do not go to a hospital.',
 body:['A hospital emergency room can cost thousands of dollars. Your insurance may not pay all of it.','For anything that is not an emergency, you have two much cheaper choices.','One. Teladoc. A real doctor, by video on your phone. It is included in your insurance and costs you nothing.','Two. An urgent care clinic. You walk in, no appointment. It costs much less than a hospital.','Keep every bill and every receipt. You cannot claim anything back later without them.'],
 need:['Your insurance card','Every bill, with the list of charges on it','Any receipt for money you paid yourself'],
 act:{label:'Send me the medical guide', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Medical Help template, with offices version if the employer matches', captures:'Nothing', notify:'Nobody on view. Coordinator if hospitalised is selected', log:'Send logged. Case row if hospitalised', status:'fix', note:'Template still contains unfilled Hospital List and Urgent Care List placeholders and currently auto sends overnight. Fix the placeholders before this tile goes live.'}},
{s:'life', q:'I want to see a doctor', sub:'Teladoc, urgent care, appointments', g:'Medical and safety', ic:'doctor', r:'Answer', k:'doctor appointment teladoc urgent care clinic gp family doctor prescription pharmacy medicine see someone book',
 you:'You are covered from <b>{dsStartF}</b> to <b>{dsEndF}</b>. Have your policy number in front of you before you call anyone.',
 lead:'Start with Teladoc. It is in your insurance, it works on your phone, and it costs you nothing.',
 body:['Teladoc is a real doctor, by video or phone call.','Use it for a fever, a rash, a cough, a stomach problem, or an infection. It is the fastest way to be seen.','They can send a prescription to a pharmacy near you.','Can they not help you by video? Then go to an urgent care clinic. You walk in. No appointment needed. Take your insurance card and your passport.','Do not go to a hospital emergency room unless it is a real emergency. The same visit there can cost ten times more, and you may wait many hours.','Do not look for a family doctor. Your programme is too short. They book weeks ahead, and most will not take a new patient at all.','Here you show your insurance or pay at the desk before you are seen. Not after. Ask what the visit costs before you say yes.','Keep every bill, every receipt and every prescription. You cannot claim anything back without them.'],
 need:['Your insurance card and your policy number','Your passport','The name of any medicine you already take'],
 act:{label:'Send me the medical guide', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Medical Help template, with offices version if the employer matches', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'fix', note:'Separate from sick or hurt on purpose. That tile is triage, this one is mechanics: how you actually get seen and what it costs. Same template behind both, and it still carries unfilled Hospital List and Urgent Care List placeholders and auto sends overnight. Fix those before either tile goes live, because this is the tile that sends someone to a specific clinic.'}},
{s:'life', q:'I have a toothache', sub:'Dentist, dental cover, tooth pain', g:'Medical and safety', ic:'tooth', r:'Answer', k:'tooth toothache dental dentist teeth wisdom filling extraction cavity gum pain mouth abscess crown',
 you:'Your insurance runs <b>{dsStartF}</b> to <b>{dsEndF}</b>. Teeth are almost certainly not included in it.',
 lead:'Call your insurance before you book. A dentist here asks you to pay on the day.',
 body:['Most J-1 insurance pays for a tooth only if you broke it in an accident.','Normal toothache, fillings, pulling a tooth, wisdom teeth. These are usually not covered at all.','So call the number on your insurance card first. Ask two questions. Does my plan cover emergency dental? And how much is the limit?','Do not go to a hospital emergency room for a toothache. They cannot fix a tooth. They give you painkillers and a bill for hundreds of dollars.','When you find a dentist, ask for two prices before you agree to anything. The price to look at it. And the price to fix it.','Prices are not fixed here and they are not printed anywhere. You have to ask.','Dental schools and community health clinics cost much less than a private dentist. Ask your CHI team what is near you.','Did you break the tooth in an accident? That is different, and it may be covered. Use the accident tile instead.'],
 need:['Your insurance card','Did it start with an accident','How many days it has hurt'],
 act:{label:'Ask my CHI team what is near me', kind:'team'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Small tile, real money. Dental came up as its own case type this season and the medical template says nothing about it, so every one of these arrives as a message. The answer is mostly the same everywhere: it is not covered, do not use an emergency room, ask the price first. The only part that varies is the nearest low cost clinic, which is the same per host city gap as the unfilled Hospital List and Urgent Care List placeholders already sitting in the medical template.'}},
{s:'life', q:'Where do I find my insurance card', sub:'Insurance card, policy number, cover dates', g:'Medical and safety', ic:'inscard', r:'Answer', k:'insurance card policy number health cover proof portal download find lost medical coverage',
 you:'You are covered from <b>{dsStartF}</b> to <b>{dsEndF}</b>. The dates on your card should match those two exactly. Do they not match? Tell your CHI team.',
 lead:'Your card is in your CHI portal. Download it today. Not on the day you need it.',
 body:['Log in to the portal. Open your profile. Download the card.','Then take a photo of it and keep the photo on your phone. A clinic asks for it while you stand at the desk, and the signal there is often bad.','Print one copy. Keep it with your passport. Phone batteries die in waiting rooms.','Your policy number is on the card. Every clinic, hospital and pharmacy asks for that number before they help you.','Look at the dates on the card. Compare them with your programme dates.','Does your card end before your programme ends? Tell your CHI team today. Fix that now, not in an emergency.','Cannot log in, or the card is not there? Tell your CHI team and they will send it to you.'],
 need:['Your CHI portal login'],
 act:{label:'Send me my insurance card', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Get Health Insurance Card template', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'live', note:'Template already exists, so this one is ready to wire. It is the enabling tile for accident, sick or hurt and toothache: none of those three go well if the participant cannot produce a policy number. Worth also firing it on arrival rather than waiting to be asked, since the cost of them not having it is a clinic refusing to treat or billing at the uninsured rate.'}},
{s:'life', q:'I feel unsafe or I am being harassed', sub:'Safety, harassment, threats', r:'Team', mo:['intervention','Intervention Required immediately, marked time sensitive.'], g:'Medical and safety', ic:'shieldalert', k:'unsafe harassed harassment threat assault scared danger touch abuse',
 lead:'A person will read this. Nothing automatic is sent.',
 body:['If you are in immediate danger, call 911 first.','Then tell your CHI team. You do not have to write it well or have proof. Write what happened in whatever words you have.'],
 need:[],
 act:{label:'Message my CHI team now', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing. Never any automatic reply', captures:'Free text only, no required fields', notify:'Coordinator and manager immediately', log:'Case row, category Wellbeing, severity Escalating', status:'live', note:'No form gate, no required fields, no auto reply. 911 stays inside this tile.'}},
{s:'life', q:'I am struggling or homesick', sub:'Homesick, lonely, low, stressed', r:'Team', g:'Medical and safety', ic:'handsheart', k:'homesick struggling sad lonely depressed stressed mental health cry help',
 lead:'A person will read this. Nothing automatic is sent.',
 body:['A lot of participants feel this around week three, when the newness wears off and the work is hard. It is common and it passes for most people.','If you want to talk to someone right now and not wait, call or text 988. It is free and available all day and night.'],
 need:[],
 act:{label:'Message my CHI team', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing. Never any automatic reply', captures:'Free text only', notify:'Coordinator', log:'Case row, category Wellbeing', status:'live', note:'988 stays inside this tile. No auto reply, no form gate.'}},
{s:'life', q:'I lost my passport or another document', sub:'Lost passport, lost DS-2019, stolen', r:'Team', mo:['custom','No template exists for this. The DS-2019 reprint request goes to MO carrying name, SID, DS Number, agency, program dates, employer, shipping address and the circumstances, and the 75 dollar fee is acknowledged before it is sent.'], g:'My documents and travel', ic:'passportq', k:'lost passport stolen document ds2019 missing police report consulate replace',
 you:'You are coming through <b>{agencyName}</b> in <b>{country}</b>. A replacement DS-2019 is issued by the CHI main office and costs 75 dollars.',
 lead:'Get a police report first. Your consulate and your insurance both need it.',
 body:['Lost and stolen are different. If it was stolen, ask for the report number, because insurance will not process a claim without it.','Your visa lives inside your passport and can only be replaced outside the United States. That means you can finish your program and go home, but you cannot leave the country and come back in. Do not book Canada or a cruise.','A replacement DS-2019 costs 75 dollars and is issued by the main office. If your passport and DS-2019 went missing together, that is one incident with two separate replacement paths running at the same time.'],
 clock:{l:'Do this first', t:'Police report, before anything else.'},
 need:['Police report or report number','What exactly was lost','Your shipping address for a replacement DS-2019'],
 act:{label:'Report a lost document', kind:'form'},
 w:{trigger:'Form submitted', fires:'Consulate details for the participant Birth Country, plus DS-2019 fee acknowledgment if applicable', captures:'What was lost, police report, shipping address', notify:'Coordinator, main office for DS-2019 reprint, DoS branch if passport or DS-2019', log:'Case row, category Compliance. DoS Notified column set', status:'build', note:'Consulate lookup runs off Birth Country in the roster and must name the real consulate, address, phone and hours. The 75 dollar fee is acknowledged before submission, not after. Open question: what is the DoS reporting window and does it differ by document.'}},
{s:'life', q:'I need a letter or a document from CHI', sub:'Proof of address, DS-2019 copy, letters', r:'Answer', g:'My documents and travel', ic:'letter', k:'letter document proof address copy ds2019 verification employer letter',
 lead:'Two things are already in your portal. Your DS-2019 copy, and your proof of address.',
 body:['Download those two yourself. You do not need to wait for anyone.','Do you need something else, like a letter for a bank or a landlord? Then ask your CHI team.','When you ask, say three things. Who the letter is for. What it has to say. And the date you need it by.','Without those three, someone has to write back and ask, and you wait another day.'],
 need:['Who the letter is for','What it has to say','The date you need it by'],
 act:{label:'Request a letter', kind:'team'},
 w:{trigger:'Form submitted', fires:'Portal link first. Letter drafted only if the portal does not cover it', captures:'Recipient, purpose, deadline', notify:'Coordinator', log:'Case row, category Communication', status:'build'}},
{s:'life', q:'I cannot get into my CHI portal', sub:'Login, password, wrong email', g:'My documents and travel', ic:'padlock', r:'Team', k:'portal login log in cannot access password forgot reset locked out account email wrong link website sign in cant get in username',
 you:'Your record is under <b>{emailMask}</b>. If you are typing a different address, that is almost certainly why you cannot get in.',
 lead:'Try the email address on your application first, then use the password reset. Do not make a second account.',
 body:['Almost everything this page points you at lives in the portal: your job offer, your DS-2019, your sponsor letter and your forms. It is worth fixing today rather than on the day you need one of them.','The most common cause is the address. People type the personal email they use every day, while the account is under the one their agency put on the application. Try that one first.','If the address is right, use the password reset link and then check your spam and promotions folders. The reset email is nearly always sitting in one of them.','If the reset email never arrives, the address is not the one on your record. Tell your CHI team which address you are trying and they will tell you which one your account is under.','Do not create a second account. A duplicate splits your documents across two records, and then nothing is where you expect it to be.','If you have never had a login at all, ask your agency first. They open your file before CHI does.'],
 need:['The email address you are trying','A screenshot of the error you get'],
 act:{label:'Tell my CHI team I cannot log in', kind:'team'},
 w:{trigger:'Form submitted, or the bar button tapped from any board', fires:'Nothing automatic', captures:'Email address attempted, error message', notify:'Coordinator', log:'Case row, category Portal Access', status:'build', note:'Reachable from the bar on every screen, not only from this board, because twenty three other tiles tell a participant to go to the portal and every one of them fails silently if they cannot get in. Confirm the real reset flow and the portal URL before this goes live, and if a self service reset already exists the action should point straight at it rather than at a person.'}},
{s:'life', q:'My Social Security card has not come', sub:'Applied, but nothing in the post', g:'My documents and travel', ic:'cardwait', r:'File', k:'social security card not received never came missing lost post mail four weeks status check replacement moved address ssn number employer asking',
 you:'You applied for a number you will need before <b>{dsEndF}</b>. Chase it now, because once you leave it is very hard to fix from home.',
 lead:'Wait four weeks from the day you applied. After that it is not coming on its own and you have to chase it.',
 body:['The card is posted to the address you gave the Social Security office, and it normally takes two to five weeks. Before four weeks, the answer is to wait.','Check the post properly first. In shared seasonal housing, mail for a name that is not on the box is often put aside or sent back. Write your name on your mailbox and ask your employer or housing manager whether anything came for you.','If you moved after you applied, the card went to the old address and it will not follow you. You have to tell the Social Security office and ask for a replacement. Tell CHI your new address at the same time, because your SEVIS record has to match where you actually live.','After four weeks with nothing, go back to the Social Security office with your receipt, or call them, and ask them to check the status. Take your passport, your DS-2019 and your printed I-94 again.','Some applications simply fail, most often because the SEVIS record was not validated on the day it was made. If that is what happened you have to apply again, and there is no shortcut around it. Better to find that out in week five than in week twelve.','You can keep working while you wait. Your employer needs the number, not the card, and you can give it to them the moment you know it. If anyone is cutting your hours or holding your pay over a missing card, tell CHI, because that is not allowed.','Do not go home without the number. Your W-2 and any tax overage you claim next April both need it.'],
 clock:{l:'Chase it before you fly home', t:'Once you leave the United States a missing Social Security number becomes very hard to fix, and you need it to file your tax return next April.'},
 need:['Your SSN receipt, the one you kept','The date you applied','The address you gave the Social Security office','The address you live at now'],
 act:{label:'Tell CHI my card has not come', kind:'form'},
 w:{trigger:'Form submitted, and automatically at DS Start plus 45 where Has Social Security Card is still blank', fires:'SSN chase steps template', captures:'Application date, address applied with, current address, whether they have moved', notify:'Coordinator', log:'Case row, category Social Security. Has Social Security Card left blank until confirmed', status:'build', note:'The apply tile is the highest volume item on the arrival board, and this is the half of it that has never had an answer written. CHI does not collect the application receipt, so the trigger cannot wait for one: it has to fire on time alone, forty five days after the start date with the card still blank. Catching a moved address is the single highest value line here, because that is the failure that silently costs the whole number.'}},
{s:'life', q:'Address verification for the bank', sub:'Proof of address, for the bank', g:'My documents and travel', ic:'addressdoc', r:'Answer', k:'address verification proof of address bank account open document letter residence where i live portal download branch',
 you:'You are at <b>{employer}</b> in <b>{location}</b>. The proof of address in your portal uses the housing address CHI has for you. Open it and check that address is right.',
 lead:'It is already in your CHI portal. Download it yourself. You do not need to ask anyone.',
 body:['Banks here want proof that you really live where you say you live.','Your portal has a proof of address document. It has your name and your US address on it.','Print it. Take it with your passport and your DS-2019. Some branches want all three.','Some branches want a second proof too. A pay stub with your address on it works. So does a short letter from your employer.','First, check the address on it. Is it wrong or old? Fix your address with CHI before you go to the bank.','This matters more than the bank. That document uses the address CHI has for you. A wrong address here means a wrong address on the government system too, and that is the bigger problem.','Did a branch say no? Ask them to write down exactly what they will accept. Send that to your CHI team. Branches all ask for different things, and this is nearly always fixable.'],
 need:['Your CHI portal login','Your passport','Your DS-2019'],
 act:{label:'Ask my CHI team', kind:'team'},
 w:{trigger:'Tile opened', fires:'Nothing sends. The document is already in the portal', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'live', note:'The portal already holds this alongside the DS-2019 copy, so the tile is a pointer rather than a request. The useful part is the warning: the document is generated from the roster address, so a participant who finds it wrong has just discovered that their SEVIS address is wrong too. That should route them to the address change tile rather than to the bank.'}},
{s:'life', q:'Can I travel inside or outside the United States', sub:'Travel, Canada, cruise, other states', r:'Answer', g:'My documents and travel', ic:'globeplane', k:'travel canada cruise mexico trip vacation outside country other state puerto rico signature entries visa re entry',
 you:'Your programme runs <b>{dsStartF}</b> to <b>{dsEndF}</b>. You must be back inside the United States before <b>{dsEndF}</b>. Not on that day. Before it.',
 lead:'Inside the United States, yes, go. Leaving the country needs four things first.',
 body:['One. Look at your visa. Find the word Entries. Does it say M? M means multiple, so you can leave and come back. Does it say S? S means single. You cannot come back. Stop here.','Two. Your return flight must land in the United States before the end date on your DS-2019. Book a few days earlier than that date, not the day itself.','Three. Ask your employer for the time off, in writing. Your trip cannot get in the way of your job.','Four. Email a clear photo or scan of your whole DS-2019 to CHIWT@chinet.org. Ask for a travel signature. Do this at least two weeks before you go.','Canada counts as leaving. So does one day away. So does a cruise that stops in another country.','There is no short trip that is too short to count.','Puerto Rico is part of the United States. No signature. No steps. You do not need to email about it.'],
 clock:{l:'Before you book anything', t:'Ask for your travel signature two weeks ahead. Without a valid one, the border can refuse to let you back in, even when everything else is correct.'},
 need:['Your visa, to check the word Entries','A clear photo of your whole DS-2019','Your employer saying yes, in writing','The day you leave and the day you come back'],
 sample:{title:'Email to send to CHIWT@chinet.org', lines:[
   'To: CHIWT@chinet.org',
   'Subject: Travel Signature Request, {name}, SID {sid}',
   'Attach: a clear full page scan of your DS-2019',
   '',
   'Hello CHI Team,',
   '',
   'I am writing to request a travel signature on my DS-2019.',
   '',
   'Full name: {name}',
   'Student Program ID: {sid}',
   'Employer: {employer}, {location}',
   'Programme dates: {dsStartF} to {dsEndF}',
   'Visa type: J-1, Entries M',
   '',
   'Travel destination: [country and city]',
   'Departure date from the United States: [date]',
   'Return date to the United States: [date]',
   '',
   'My employer has approved this time off. A clear scan of my DS-2019 is attached. Please sign it and send it back before my departure date.',
   '',
   'Thank you,',
   '{name}',
   '[your email]',
   '[your WhatsApp number]']},
 act:{label:'Send me the travel guide', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Travel Outside US template', captures:'Nothing on view', notify:'Signature request goes to CHIWT, not to the coordinator', log:'Send logged against SID', status:'fix', note:'Template content is complete and correct. Two things wrong with it. It has no name merge field at all, so it opens with the literal text Hi followed by a dash. And the sample email inside it is written with blank placeholders the participant has to fill in by hand, when the page already knows their name, SID, employer, location and programme dates. The tile version fills those in, which is the difference between a template and an answer. This tile never reaches the coordinator queue, which is the point of it.'}},
{s:'life', q:'I am being evicted', sub:'Told to leave, notice, back rent', g:'Where I live', ic:'housealert', r:'Team', hz:1, k:'evicted eviction notice told to leave kicked out back rent behind owe landlord removed housing lose my room',
 you:'Your placement is <b>{employer}</b> in <b>{location}</b>. Tell your CHI team today, whatever the notice says.',
 lead:'Tell your CHI team today. Do not wait to see what happens next.',
 body:['A landlord here usually cannot put you out the same day, but the process moves quickly and it is far easier to stop at the start than after a date has passed.','Find out what it is actually about. Most of the time it is unpaid rent, and most of the time that is a deduction that quietly stopped coming out of your pay, or a roommate who did not pay their share.','If it is rent, ask for the exact amount owed and the exact dates it covers, in writing. Then check it against your pay stubs before you agree that you owe it.','If it is a complaint about noise, damage, guests or pests, ask what specifically and by when it has to stop.','Do not sign anything and do not agree to leave until your CHI team has seen the notice.','Photograph the notice, or forward the message, exactly as you received it.','If you share the unit, this affects everyone in it. Tell the others today, because usually they have the same notice coming.','Keep going to work. Losing the job on top of this turns one problem into two, and the job is what pays the rent.'],
 need:['A photo of the notice, or the message you were sent','The amount owed and the dates it covers','Your pay stubs showing the rent deduction','Who else lives in the unit'],
 act:{label:'Message my CHI team now', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing automatic. This tile never auto replies', captures:'Notice image, amount claimed, dates, roommates, whether rent is deducted from pay', notify:'Coordinator and manager immediately, marked time sensitive', log:'Case row, category Housing, severity High. Every other participant at the same address flagged for a check', status:'build', note:'Split out from the housing problem tile because the clock is different. There were six back rent warnings this season, every one of them from a single agency and four of them at the same store. That pattern is the reason the trigger has to check the whole address rather than the one person who wrote in: when one participant is behind on rent at a shared placement, the others usually are too and nobody has told them yet.'}},
{s:'life', q:'There is a problem at my housing', sub:'Repairs, rent, roommates', g:'Where I live', ic:'housetools', r:'Team', hz:1, k:'housing house problem rent roommate landlord repair broken heating water pests noise during program deduction',
 you:'Your placement is <b>{employer}</b> in <b>{location}</b>.',
 lead:'Take dated photos, then tell your CHI team what is wrong.',
 body:['For repairs, tell your landlord in writing first and keep the message. CHI needs to be able to show that you asked and when.','For rent taken twice, or a deduction you do not recognise, send your pay stub as well as the rent receipt. Those two together are what settles it.','For roommates, say something within two days and use I statements. Two weeks later you are angry and the conversation goes badly.','Keep your kitchen clean and your rubbish sealed. Most deductions at the end of the season come from pests, and in shared housing one person costs everybody.','If you have been told to leave, or you have been given any kind of notice, that is the eviction tile instead. Do not wait.'],
 need:['Dated photos','What you told the landlord and when','Rent receipts or the deduction on your stub'],
 act:{label:'Message my CHI team', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing automatic', captures:'Photos, landlord contact record, rent evidence', notify:'Coordinator', log:'Case row, category Housing. Housing sheet fed', status:'build', note:'Housing sheet exists with zero rows against 26 housing cases. Built and never fed, same as Job Changes and Paycheck Log. Build the feeder before the list.'}},
{s:'end', q:'I want to go home early', sub:'Shorten my program, leave early', r:'File', mo:['shorten','Shorten Program, carrying reason, employer, location, position, first and final day of work, whether the employer was given one week notice, and the departure city and date. Fires on the departure date, and only when the 16 day branch is met.'], ic:'planeback', k:'go home early shorten leave early end program finish early quit go back',
 you:'Your programme ends <b>{dsEndF}</b>. That is <b>{daysLeft}</b> days from today.',
 lead:'Tell your employer first, then file this. Leaving without notice affects the next participant they take.',
 body:['Your CHI team needs your real last day of work and your real flight date. Not an estimate.','Nothing is sent anywhere when you file. It waits until the day before you fly, so if your plans change you only have to tell your CHI team once.','The day before you leave you will get an email from your CHI team. If you are going home 16 days or more before your programme end date, that email will remind you to keep your boarding pass, because you have to send a photo of it after you land.','Keep the boarding pass stub in your hand luggage, not in your checked bag.'],
 need:['Your last day of work','Your flight home date','Your flight itinerary','Whether you have told your employer'],
 sample:{title:'Email you can send your employer', lines:[
   'Subject: My last day of work',
   '',
   'Dear [manager name],',
   '',
   'I am writing to let you know that my last day of work will be [date].',
   '',
   'I am leaving the programme early and I have told CHI. I wanted to give you as much notice as I can so you can plan the schedule.',
   '',
   'Please tell me if you need anything from me before then.',
   '',
   'Thank you for the season.',
   '',
   '[Your name]',
   '[Your job title]']},
 act:{label:'File to go home early', kind:'form', url:'tally.so/r/pbLbZP'},
 w:{trigger:'Form submitted, then held. Nothing fires on submission',
  fires:'Departure date minus 1 day, two sends at once. 1. Shorten Program to the main office, carrying reason, employer, location, position, first and final day of work, whether the employer was given one week notice, and the departure city and date. 2. A reminder to the EV that they must photograph their boarding pass and send it. Both are gated on the same test: the departure has to be 16 or more days before DS End. Under 16 days neither send happens, the case stays as an internal row, and nobody is chased for proof',
  captures:'Last work day, departure date as a real date picker not free text, reason, itinerary, employer told yes or no. Email and phone are looked up from the SID rather than asked for',
  notify:'Main office only when the 16 day branch is met. Coordinator sees the row either way',
  log:'Case row, category Compliance, Early Departure. Proof of return chase scheduled for departure plus 3 and plus 7',
  status:'fix',
  note:'Highest value build on the board. Form is live at tally.so/r/pbLbZP. Programme Shortening is the largest single case type in the tracker at 21 of 213 and it costs only 23 replies, because it already moved to a form. Four things have to be right. The trigger watches the date rather than firing and forgetting, because people move flights constantly. A submission whose departure date has already passed fires immediately instead of waiting for a date in the past. 15 versus 16 days is a sharp boundary, so the departure field must be a real date picker and DS End must be correct on the roster. And the day before matters: on the day itself they are already travelling, so the boarding pass reminder has to reach them while they can still act on it. The proof itself is a second short form with one required upload field and example photos of a boarding pass stub and a luggage tag, chased at departure plus 3 and plus 7. It has to be an upload field, not an email reply, because a reply lets people send words instead of files: one sent a booking confirmation, one sent the wrong document, and one replied with the template placeholder still in the message and nothing attached. There is no tile for it, on purpose. Nobody comes looking for proof of return, it is pushed to them by the trigger. Existing bugs to clear first: the form has no email or phone field, and the proof of return address is wrong in three separate places'}},
{s:'end', q:'When do I have to leave the United States', sub:'Grace period, 30 days, last date', r:'Agency', ic:'hourglass', k:'grace period 30 days leave country last date when go home stay after',
 you:'Your programme ends <b>{dsEndF}</b>. You cannot work after that date, and the very last day you may remain in the United States is <b>{graceEnd}</b>.',
 lead:'The 30 days after your DS-2019 end date is an outside limit, not a plan.',
 body:['You may stay in the United States for up to 30 days after your program end date. You cannot work in those days and you cannot leave and re-enter.','The real question is when your university term starts. CHI does not have your academic calendar, so if you are not sure of your own term dates, ask your agency at home before you book.'],
 need:['Your DS-2019 end date','Your university term start date'],
 act:{label:'Message my agency', kind:'agency'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Routes to the agency named from Agency Office Code. Written this way because CHI has been asked to confirm return dates it cannot know.'}},
{s:'end', q:'Can I travel before I go home', sub:'Travel at the end, grace period', r:'Answer', ic:'depart', k:'travel outside us canada mexico cruise grace period leave country re enter signature end of program trip',
 you:'Your programme ends <b>{dsEndF}</b> and you may stay until <b>{graceEnd}</b>. Any trip outside the United States has to bring you back before <b>{dsEndF}</b>. After that date you cannot re-enter at all.',
 lead:'It depends on one thing. Are you travelling before your end date, or after it?',
 body:['BEFORE your end date, do the four steps.','One. Check your visa says Entries M. Two. Get your employer to say yes in writing. Three. Email a clear photo of your whole DS-2019 to CHIWT@chinet.org and ask for a travel signature, at least two weeks ahead.','Four. Your return flight must land in the United States BEFORE your end date. Not on that day. Before it. If you come back after that date, you will not be let in.','AFTER your end date you are in your grace period. That is a short time you are allowed to stay.','In your grace period you can travel inside the United States. That is fine.','But if you leave the country in your grace period, it ends the moment you go. You cannot come back. Not even the next day.','Puerto Rico is part of the United States. A trip there is not leaving. No signature needed.','A cruise that stops in another country IS leaving. Even if it starts and ends at a US port.'],
 clock:{l:'Before you book anything', t:'Ask for your travel signature two weeks ahead. Only ask for one if you will be back before your programme end date.'},
 need:['Your visa, to check the word Entries','A clear photo of your whole DS-2019','Your employer saying yes, in writing','The day you leave and the day you come back'],
 act:{label:'Send me the travel guide', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Travel Outside US template', captures:'Nothing on view', notify:'Signature request goes to CHIWT, not to the coordinator', log:'Send logged against SID', status:'fix', note:'Same template as the working stage tile and the same missing name merge field. The end of programme wording has to differ, because after DS End there is no signature to give and the real answer is that leaving ends the grace period. Worth splitting the template in two, or adding one paragraph that fires only when DS End is inside 30 days.'}},
{s:'end', q:'How do I extend my insurance for my travel period', sub:'Cover after my programme ends', r:'File', ic:'shieldplus', k:'insurance extend cover grace period travel after end medical health uninsured buy extension',
 you:'You are covered from <b>{dsStartF}</b> to <b>{dsEndF}</b>. If you stay in the United States after <b>{dsEndF}</b>, right up to <b>{graceEnd}</b>, you have no medical cover at all unless you buy it.',
 lead:'Your insurance ends on the same day your programme ends. The grace period does not extend it by a single day.',
 body:['A lot of participants find this out the wrong way. You are allowed to stay for up to 30 days after your programme ends, and many people travel in those weeks, but every one of those days is uninsured.','One visit to a clinic in that window can cost more than the extension would have.','Ask your CHI team before your end date, not after. Cover usually cannot be added once it has already lapsed.','Tell them the exact dates you want covered and the date of your flight home. The cost depends on how many days you are asking for.','This is the same problem as arriving early, at the other end of your programme. If you did both, you need cover at both ends.'],
 clock:{l:'Ask before your end date', t:'Once cover has lapsed it usually cannot be added back. Ask while your programme is still running.'},
 need:['The first and last date you want covered','Your flight home date','Your programme end date'],
 act:{label:'Ask about extending my insurance', kind:'form'},
 w:{trigger:'DS End minus 21, and on tile open', fires:'Insurance extension options with a cost per week', captures:'Dates requested, flight home date', notify:'Coordinator', log:'Case row, category Compliance. Extension dates written to the roster', status:'build', note:'The mirror image of the early arrival gap, and neither trigger exists yet. Both are the same failure: insurance runs DS Start to DS End and nothing watches either edge. The early end cost about 1450 dollars of exposure across 14 people this season. The late end is not measured at all, because nobody asks until they are already uninsured and usually already sick.'}},
{s:'end', q:'How do I get my final paycheck', sub:'Last pay, after I stop working', r:'Answer', ic:'finalpay', k:'final paycheck last pay wages after leaving money owed direct deposit close bank account payroll last check',
 you:'Your programme ends <b>{dsEndF}</b>. Ask <b>{employer}</b> payroll two things now. What date is my final pay? And how will it reach me?',
 lead:'Go and ask payroll before your last shift. Not after it.',
 body:['Payroll is the office that pays you. Ask them these things while you are still there.','One. What is the exact date of my last pay? It usually comes one or two pay periods after your last shift, so it can arrive after you have flown home.','Two. How will it reach me? Straight into my bank? In the post? Or held here for me?','Is it going in the post? Give them an address that still works after you leave. A roommate who is staying is usually better than your home address.','Do not close your US bank account yet. Closing it early is the number one reason a final payment fails and goes back to the employer. Then it takes months.','Give payroll the same address for your W-2 in January. Do it in the same conversation, not a second one.','Keep your last pay stub. If money is missing, that paper is what proves it.'],
 need:['Your last day of work','The pay date payroll gave you','The address payroll has for you','Your US bank account, still open'],
 sample:{title:'Email you can send payroll', lines:[
   'Subject: My final paycheck',
   '',
   'Dear [manager or payroll],',
   '',
   'My last day of work is [date]. Please can you tell me three things:',
   '',
   '1. What date my final pay will be issued',
   '2. Whether it will be direct deposit or a check sent in the post',
   '3. If it is sent in the post, what address you have for me',
   '',
   'I want to make sure it reaches me after I leave. Please use the same address for my W-2 in January.',
   '',
   'Thank you,',
   '[Your name]',
   '[Your job title]']},
 act:{label:'Ask my CHI team about my final pay', kind:'team'},
 w:{trigger:'DS End minus 14, together with the W-2 send', fires:'Final pay and forwarding address reminder', captures:'Forwarding address if submitted', notify:'Coordinator only if the participant reports it never arrived', log:'Send logged against SID', status:'build', note:'No template written. This and the W-2 tile ask for the same thing, a working address after departure, so they should be one send at DS End minus 14 rather than two. Chasing a final paycheck after someone has flown and closed their account is the expensive version of this conversation.'}},
{s:'end', q:'Should I close my US bank account', sub:'Closing the account, final pay, overages', r:'Answer', ic:'bankclose', k:'close bank account keep open final pay overage overages refund tax money dormant fee statement',
 you:'Your programme ends <b>{dsEndF}</b>. Ask <b>{employer}</b> for your final pay date before you decide anything about the account.',
 lead:'Not yet. Wait until your final pay, and anything else you are owed, has arrived.',
 body:['Your final paycheck can come one or two pay periods after your last shift. That is often after you are already home.','Are you claiming a tax overage? That money comes months later. A closed account is the number one reason it fails and has to be sent again.','Some banks charge a fee every month once you stop using the account. Ask your bank two things. What do you charge? And what does it cost to keep this open from my country?','When you do close it, do it after the final pay has arrived. And get a copy of your last statement first.','Never leave your card, your login, or your account details with anyone to use after you go. Not a friend. Not a roommate.'],
 need:['Your final pay date from payroll','Are you claiming a tax overage','What your bank charges on an unused account'],
 act:{label:'Ask my CHI team', kind:'team'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Belongs in the same DS End minus 14 send as the final pay and W-2 reminder. All three are the same underlying problem: money that arrives after the participant has gone.'}},
{s:'end', q:'How do I claim my tax overages back', sub:'W-2, filing, and tax taken in error', r:'Answer', ic:'formpct', k:'w2 w-2 tax overage overages back claim return irs file january april deadline fica oasdi social security medicare 843 8316 nonresident nonresident alien overpaid too much tax',
 you:'<b>{employer}</b> sends your W-2 at the end of January. Before you leave, give their payroll an address that still works then.',
 lead:'There are two different kinds of money, and two different ways to get them back.',
 body:['Read this part first. Your W-2 comes from your employer at the end of January. It is the paper that shows what you earned and what tax you paid.','Before you leave, give your workplace an address that still works in January. That one step stops most of the trouble.','KIND ONE. Too much income tax. This happens to almost everyone on a summer wage.','You get it back by sending a tax form to the US government in April. You do this from home. You do not need to be in the USA.','Most participants are what the US calls a nonresident. That means you use a different form from an American. Using the American form is the most common mistake, and it gives you the wrong number.','KIND TWO. Social Security and Medicare tax. On your pay stub it looks like FICA, OASDI, SS, Med, or FED MED EE.','J-1 participants do not pay these. If it came out of your pay, it was a mistake.','This money does NOT come back in April. It never does, no matter what anyone tells you. It has its own way.','For this one, ask your employer first. In the same tax year they can usually just fix it and pay you. That is much faster than anything else.','Will they not do it, or say they cannot? Then you ask the government yourself. You send Form 843 and Form 8316.','With those two forms you send copies of: your W-2, the visa page of your passport, your I-94, and a note from your employer saying what they paid back. Will they not write that note? Write your own. Say that you asked and what they said.','These forms go to the IRS office where your employer sends its payroll paperwork. That is a different address from your tax form.','This one takes months. Sometimes most of a year. So keep an address and a bank account that will still reach you.','Nobody needs a share of your money to do any of this. Be careful with any company that charges a big fee, or asks for your bank login.','CHI cannot fill in these forms for you and cannot give tax advice. But this is the order it goes in.'],
 clock:{l:'Before you fly home', t:'Give payroll an address that still works in January, and do not close your US bank account until everything owed to you has arrived.'},
 need:['Your W-2','Your last pay stub','An address that still works in January','Your passport visa page and your I-94, for kind two'],
 act:{label:'Read this and go back', kind:'answer'},
 w:{trigger:'Tile opened, and on a send at DS End minus 14', fires:'Nothing on view', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Two questions were being answered as one and they have nothing in common. The April return returns an income tax overage. Social Security and Medicare taken in error never comes back that way, and every participant who is told to just file gets nothing and asks again a year later. The employer first line is the one that matters most, because inside the same tax year payroll can simply correct it, and after that year closes the participant is into Form 843 and a wait of most of a year. Pairs with the payroll tile on the working board, which is where this gets caught early enough to still be cheap.'}},
{s:'end', q:'Can I come back next year', sub:'Returning, next season, second time', r:'Answer', ic:'calrefresh', k:'come back next year again return second season returnee repeat apply',
 you:'You came through <b>{agencyName}</b> in <b>{country}</b>. Apply through them again, and tell your CHI team if you want to return to <b>{employer}</b>.',
 lead:'Yes, if you are still a full time student at home.',
 body:['Apply through the same agency that sent you this time.','Apply early. They open the next season months before it starts, and the best jobs go first.','How you finish this programme matters. Leaving early without telling anyone, or being fired, shows up when you apply again.','Do you want to come back to the same employer? Tell your CHI team. Many employers ask for their old workers by name.'],
 need:['Proof you are still a student','Your agency contact'],
 act:{label:'Tell my CHI team I want to return', kind:'form'},
 w:{trigger:'DS End minus 14, plus tile', fires:'Returnee interest confirmation', captures:'Interest, preferred employer, student status', notify:'Coordinator digest at season end', log:'Roster flag for next season recruitment', status:'build', note:'Not a failure question, an interest question. EYW participants raise it at 47 percent against a 10 percent baseline. Send it as an offer, not a correction.'}}
];


